diffs.replacement:
{
  "name": "chef.ai - Caderno da Pati",
  "description": "Um caderno de receitas inteligente para a família da Pati, com transcrição por IA e organização automática.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

export interface Profile {
  id: string;
  name: string;
  photoUrl: string;
  birthDate: string;
}

export interface Recipe {
  id: string;
  title: string;
  category: 'entradas' | 'salgados' | 'sobremesas' | 'bebidas' | 'outros';
  ingredients: string;
  instructions: string;
  authorId: string;
  authorName: string;
  externalLink?: string;
  imageUrl?: string;
  createdAt: number;
}

export enum AppView {
  LOGIN,
  PROFILE_SELECT,
  PROFILE_CREATE,
  HOME,
  RECIPE_DETAIL,
  RECIPE_EDIT,
  AI_TOOLS
}

export const FAMILY_PASSWORD = "2610";

export const CATEGORIES = [
  { id: 'entradas', label: 'Entradas', icon: '🥗' },
  { id: 'salgados', label: 'Salgados', icon: '🥟' },
  { id: 'sobremesas', label: 'Sobremesas', icon: '🍰' },
  { id: 'bebidas', label: 'Bebidas', icon: '🍹' },
  { id: 'outros', label: 'Outros', icon: '🍽️' },
];

export const LOGO_URL = "https://i.ibb.co/nMp0TxFf/patitour-2026-02-09-T075024-154.png";
export const ICON_URL = "https://i.ibb.co/LDzRtdMp/patitour-2026-02-09-T075239-692.png";

import { GoogleGenAI, Type } from "@google/genai";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async transcribeImage(base64Image: string) {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: "image/jpeg" } },
          { text: "Você é um assistente de cozinha experiente. Transcreva esta imagem de uma receita (pode ser escrita à mão) para um formato JSON estruturado com os campos: title, ingredients, instructions e category (escolha entre: entradas, salgados, sobremesas, bebidas, outros). Responda apenas o JSON." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async transcribeVideoLink(url: string) {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Extraia a receita completa deste vídeo: ${url}. Pesquise o conteúdo se necessário para garantir fidelidade. Retorne em formato JSON com: title, ingredients, instructions e category (entradas, salgados, sobremesas, bebidas, outros).`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async getRecipeSuggestions(ingredients: string) {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Com base nestes ingredientes: ${ingredients}, sugira 3 receitas criativas que eu possa fazer. Para cada receita, forneça nome, uma breve descrição e por que combina com os ingredientes.`,
    });

    return response.text;
  }
}

export const gemini = new GeminiService();

import React, { useState, useEffect } from 'react';
import { AppView, Profile, Recipe } from './types';
import { FAMILY_PASSWORD, LOGO_URL, ICON_URL, CATEGORIES } from './constants';
import { gemini } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.LOGIN);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [activeProfile, setActiveProfile] = useState<Profile | null>(null);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');

  // Login State
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);

  // Profile Create State
  const [newProfileName, setNewProfileName] = useState('');
  const [newProfilePhoto, setNewProfilePhoto] = useState('');
  const [newProfileBirth, setNewProfileBirth] = useState('');

  // Recipe Form State
  const [editingRecipe, setEditingRecipe] = useState<Recipe | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Persistence
  useEffect(() => {
    const savedProfiles = localStorage.getItem('pati_profiles');
    const savedRecipes = localStorage.getItem('pati_recipes');
    if (savedProfiles) setProfiles(JSON.parse(savedProfiles));
    if (savedRecipes) setRecipes(JSON.parse(savedRecipes));
  }, []);

  useEffect(() => {
    localStorage.setItem('pati_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    localStorage.setItem('pati_recipes', JSON.stringify(recipes));
  }, [recipes]);

  const handleLogin = () => {
    if (passwordInput === FAMILY_PASSWORD) {
      setView(AppView.PROFILE_SELECT);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 2000);
    }
  };

  const handleAddProfile = () => {
    if (!newProfileName) return;
    const newProfile: Profile = {
      id: Date.now().toString(),
      name: newProfileName,
      photoUrl: newProfilePhoto || 'https://picsum.photos/200',
      birthDate: newProfileBirth,
    };
    setProfiles([...profiles, newProfile]);
    setView(AppView.PROFILE_SELECT);
    setNewProfileName('');
    setNewProfilePhoto('');
    setNewProfileBirth('');
  };

  const saveRecipe = (recipeData: Partial<Recipe>) => {
    if (editingRecipe) {
      setRecipes(recipes.map(r => r.id === editingRecipe.id ? { ...r, ...recipeData } as Recipe : r));
    } else {
      const newRecipe: Recipe = {
        id: Date.now().toString(),
        createdAt: Date.now(),
        authorId: activeProfile?.id || 'anonymous',
        authorName: activeProfile?.name || 'Visitante',
        title: recipeData.title || 'Sem título',
        category: recipeData.category || 'outros',
        ingredients: recipeData.ingredients || '',
        instructions: recipeData.instructions || '',
        externalLink: recipeData.externalLink,
        imageUrl: recipeData.imageUrl,
      };
      setRecipes([newRecipe, ...recipes]);
    }
    setEditingRecipe(null);
    setView(AppView.HOME);
  };

  const deleteRecipe = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir esta receita preciosa?')) {
      setRecipes(recipes.filter(r => r.id !== id));
      setView(AppView.HOME);
    }
  };

  // Views rendering
  if (view === AppView.LOGIN) {
    return (
      <div className="min-h-screen bg-pati-orange flex flex-col items-center justify-center p-6 text-white">
        <img src={LOGO_URL} alt="Logo" className="w-48 h-48 rounded-full border-4 border-white mb-8 shadow-xl" />
        <h1 className="text-4xl font-cursive mb-12">Caderno de receitas da Pati</h1>
        <div className="w-full max-w-sm space-y-4">
          <div className="relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔒</span>
            <input 
              type="password" 
              placeholder="Digite a senha da família" 
              className="w-full py-4 pl-12 pr-4 rounded-2xl text-gray-800 outline-none focus:ring-2 focus:ring-orange-300"
              value={passwordInput}
              onChange={(e) => setPasswordInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
            />
          </div>
          <button 
            onClick={handleLogin}
            className="w-full py-4 bg-white text-pati-orange font-bold rounded-2xl shadow-lg hover:bg-orange-50 active:scale-95 transition-all uppercase tracking-wider"
          >
            Entrar na Cozinha
          </button>
          {loginError && <p className="text-center text-sm font-medium">Senha incorreta, tente novamente!</p>}
        </div>
      </div>
    );
  }

  if (view === AppView.PROFILE_SELECT) {
    return (
      <div className="min-h-screen bg-white p-6 flex flex-col items-center">
        <img src={ICON_URL} alt="Logo" className="w-24 mb-6" />
        <p className="text-center text-gray-600 italic mb-8 px-4">
          "Nosso caderno de receitas virou app! Agora a gente compartilha segredos de cozinha, 
          fotografa caderninhos antigos e deixa tudo guardado aqui — com direito a 'assinatura' de quem mandou a receita. 
          Vamos cozinhar juntas, mesmo de longe?"
        </p>
        <h2 className="text-2xl font-cursive text-gray-800 mb-12">Quem está cozinhando hoje?</h2>

        <div className="grid grid-cols-2 gap-8 w-full max-w-md">
          {profiles.map(p => (
            <button key={p.id} onClick={() => { setActiveProfile(p); setView(AppView.HOME); }} className="flex flex-col items-center group">
              <img src={p.photoUrl} className="w-24 h-24 rounded-full border-2 border-transparent group-hover:border-pati-orange shadow-md object-cover mb-2" />
              <span className="font-medium text-gray-700">{p.name}</span>
            </button>
          ))}
          <button onClick={() => setView(AppView.PROFILE_CREATE)} className="flex flex-col items-center group">
            <div className="w-24 h-24 rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-3xl text-gray-300 group-hover:text-pati-orange group-hover:border-pati-orange">
              👤+
            </div>
            <span className="font-medium text-gray-400 mt-2">Novo Perfil</span>
          </button>
        </div>
      </div>
    );
  }

  if (view === AppView.PROFILE_CREATE) {
    return (
      <div className="min-h-screen bg-gray-50 p-6 flex flex-col">
        <button onClick={() => setView(AppView.PROFILE_SELECT)} className="text-pati-orange mb-6 flex items-center gap-2">← Voltar</button>
        <h2 className="text-2xl font-bold text-gray-800 mb-6">Criar Perfil de Família</h2>
        <div className="bg-white p-6 rounded-2xl shadow-sm space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">Nome Completo</label>
            <input 
              type="text" 
              className="w-full p-3 border rounded-xl"
              value={newProfileName}
              onChange={e => setNewProfileName(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">URL da Foto</label>
            <input 
              type="text" 
              placeholder="Link da imagem ou deixe em branco"
              className="w-full p-3 border rounded-xl"
              value={newProfilePhoto}
              onChange={e => setNewProfilePhoto(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">Data de Nascimento</label>
            <input 
              type="date" 
              className="w-full p-3 border rounded-xl"
              value={newProfileBirth}
              onChange={e => setNewProfileBirth(e.target.value)}
            />
          </div>
          <button onClick={handleAddProfile} className="w-full py-4 bg-pati-orange text-white rounded-xl font-bold shadow-lg">Criar Perfil</button>
        </div>
      </div>
    );
  }

  const filteredRecipes = recipes.filter(r => {
    const matchesSearch = r.title.toLowerCase().includes(search.toLowerCase()) || r.ingredients.toLowerCase().includes(search.toLowerCase());
    const matchesCategory = categoryFilter === 'all' || r.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      {/* Header */}
      <header className="bg-white p-4 shadow-sm sticky top-0 z-20 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <img src={ICON_URL} alt="Icon" className="w-10 h-10" />
          <h1 className="text-xl font-cursive text-pati-orange">chef.ai da Pati</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView(AppView.AI_TOOLS)} className="text-2xl" title="Sugestões da IA">🪄</button>
          <img 
            src={activeProfile?.photoUrl} 
            className="w-10 h-10 rounded-full border border-pati-orange cursor-pointer object-cover" 
            onClick={() => setView(AppView.PROFILE_SELECT)}
          />
        </div>
      </header>

      {/* Content */}
      <div className="p-4 max-w-2xl mx-auto">
        {view === AppView.HOME && (
          <>
            <div className="mb-6 space-y-4">
              <input 
                type="text" 
                placeholder="🔍 Buscar receitas..." 
                className="w-full p-3 rounded-2xl border-none shadow-sm focus:ring-2 focus:ring-pati-orange"
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
              <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                <button 
                  onClick={() => setCategoryFilter('all')}
                  className={`px-4 py-2 rounded-full whitespace-nowrap text-sm font-medium transition-colors ${categoryFilter === 'all' ? 'bg-pati-orange text-white' : 'bg-white text-gray-600'}`}
                >
                  Todas
                </button>
                {CATEGORIES.map(cat => (
                  <button 
                    key={cat.id}
                    onClick={() => setCategoryFilter(cat.id)}
                    className={`px-4 py-2 rounded-full whitespace-nowrap text-sm font-medium transition-colors ${categoryFilter === cat.id ? 'bg-pati-orange text-white' : 'bg-white text-gray-600 shadow-sm'}`}
                  >
                    {cat.icon} {cat.label}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              {filteredRecipes.length === 0 ? (
                <div className="text-center py-20 text-gray-400">
                  <p className="text-4xl mb-4">🥘</p>
                  <p>Nenhuma receita encontrada.</p>
                  <p className="text-sm">Que tal adicionar uma nova?</p>
                </div>
              ) : (
                filteredRecipes.map(recipe => (
                  <div key={recipe.id} className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 group transition-all" onClick={() => { setEditingRecipe(recipe); setView(AppView.RECIPE_DETAIL); }}>
                    {recipe.imageUrl && (
                      <img src={recipe.imageUrl} className="w-full h-40 object-cover" />
                    )}
                    <div className="p-4">
                      <div className="flex justify-between items-start mb-2">
                        <span className="text-xs font-bold uppercase tracking-wider text-pati-orange bg-orange-50 px-2 py-1 rounded">
                          {CATEGORIES.find(c => c.id === recipe.category)?.label}
                        </span>
                        <span className="text-xs text-gray-400">
                          {new Date(recipe.createdAt).toLocaleDateString('pt-BR')}
                        </span>
                      </div>
                      <h3 className="text-lg font-bold text-gray-800 mb-1">{recipe.title}</h3>
                      <p className="text-sm text-gray-500 mb-4 line-clamp-2">{recipe.ingredients}</p>
                      <div className="flex justify-between items-center border-t pt-3 mt-auto">
                        <span className="text-xs text-gray-600 italic">Chef: {recipe.authorName}</span>
                        {recipe.externalLink && <span className="text-xs text-blue-500">🔗 Vídeo</span>}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </>
        )}

        {(view === AppView.RECIPE_DETAIL && editingRecipe) && (
          <div className="bg-white rounded-3xl p-6 shadow-lg min-h-[80vh]">
            <div className="flex justify-between mb-4">
               <button onClick={() => setView(AppView.HOME)} className="text-pati-orange font-bold">← Voltar</button>
               <div className="flex gap-4">
                 <button onClick={() => setView(AppView.RECIPE_EDIT)} className="text-gray-400">✏️</button>
                 <button onClick={() => deleteRecipe(editingRecipe.id)} className="text-red-300">🗑️</button>
               </div>
            </div>

            {editingRecipe.imageUrl && <img src={editingRecipe.imageUrl} className="w-full h-56 object-cover rounded-2xl mb-6" />}

            <h2 className="text-3xl font-cursive text-gray-800 mb-2">{editingRecipe.title}</h2>
            <div className="flex items-center gap-2 mb-6">
              <span className="px-3 py-1 bg-orange-100 text-pati-orange rounded-full text-xs font-bold uppercase">{editingRecipe.category}</span>
              <span className="text-sm text-gray-400">Por {editingRecipe.authorName}</span>
            </div>

            <div className="space-y-6">
              <section>
                <h4 className="font-bold text-gray-700 mb-2 border-l-4 border-pati-orange pl-3">Ingredientes</h4>
                <p className="text-gray-600 whitespace-pre-wrap leading-relaxed">{editingRecipe.ingredients}</p>
              </section>

              <section>
                <h4 className="font-bold text-gray-700 mb-2 border-l-4 border-pati-orange pl-3">Modo de Preparo</h4>
                <p className="text-gray-600 whitespace-pre-wrap leading-relaxed">{editingRecipe.instructions}</p>
              </section>

              {editingRecipe.externalLink && (
                <section>
                  <h4 className="font-bold text-gray-700 mb-2 border-l-4 border-pati-orange pl-3">Link do Vídeo</h4>
                  <a href={editingRecipe.externalLink} target="_blank" rel="noopener noreferrer" className="text-blue-500 break-all underline">
                    {editingRecipe.externalLink}
                  </a>
                </section>
              )}
            </div>
          </div>
        )}

        {(view === AppView.RECIPE_EDIT || view === AppView.AI_TOOLS) && (
          <RecipeForm 
            recipe={editingRecipe || undefined} 
            activeProfile={activeProfile}
            onSave={saveRecipe} 
            onCancel={() => setView(AppView.HOME)} 
            isAiLoading={isAiLoading}
            setIsAiLoading={setIsAiLoading}
          />
        )}
      </div>

      {/* Floating Add Button */}
      {view === AppView.HOME && (
        <button 
          onClick={() => { setEditingRecipe(null); setView(AppView.RECIPE_EDIT); }}
          className="fixed bottom-6 right-6 w-16 h-16 bg-pati-orange text-white text-3xl rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-50"
        >
          +
        </button>
      )}
    </div>
  );
};

interface RecipeFormProps {
  recipe?: Recipe;
  activeProfile: Profile | null;
  onSave: (data: Partial<Recipe>) => void;
  onCancel: () => void;
  isAiLoading: boolean;
  setIsAiLoading: (v: boolean) => void;
}

const RecipeForm: React.FC<RecipeFormProps> = ({ recipe, activeProfile, onSave, onCancel, isAiLoading, setIsAiLoading }) => {
  const [formData, setFormData] = useState<Partial<Recipe>>(recipe || {
    title: '',
    category: 'outros',
    ingredients: '',
    instructions: '',
    externalLink: '',
    imageUrl: '',
    authorName: activeProfile?.name || ''
  });
  const [videoUrl, setVideoUrl] = useState('');
  const [suggestionInput, setSuggestionInput] = useState('');
  const [suggestions, setSuggestions] = useState('');

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsAiLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const result = await gemini.transcribeImage(base64);
        setFormData(prev => ({ ...prev, ...result, imageUrl: reader.result as string }));
      } catch (err) {
        alert('Erro ao transcrever imagem. Verifique sua conexão ou API Key.');
      } finally {
        setIsAiLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleVideoTranscribe = async () => {
    if (!videoUrl) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.transcribeVideoLink(videoUrl);
      setFormData(prev => ({ ...prev, ...result, externalLink: videoUrl }));
    } catch (err) {
      alert('A IA não conseguiu transcrever este vídeo automaticamente, mas salvamos o link para você!');
      setFormData(prev => ({ ...prev, externalLink: videoUrl }));
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleGetSuggestions = async () => {
    if (!suggestionInput) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.getRecipeSuggestions(suggestionInput);
      setSuggestions(result || 'Nenhuma sugestão encontrada.');
    } catch (err) {
      alert('Erro ao buscar sugestões.');
    } finally {
      setIsAiLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-3xl p-6 shadow-sm space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">{recipe ? 'Editar Receita' : 'Nova Receita'}</h2>
        <button onClick={onCancel} className="text-gray-400">Fechar</button>
      </div>

      {isAiLoading && (
        <div className="bg-orange-50 p-4 rounded-xl border border-orange-200 animate-pulse text-center">
          <p className="text-pati-orange font-medium">👨‍🍳 Chef.AI está trabalhando na sua receita...</p>
        </div>
      )}

      {/* AI Tools Section */}
      {!recipe && (
        <div className="bg-gray-50 p-4 rounded-2xl space-y-4">
          <h3 className="text-sm font-bold text-gray-500 uppercase">Ferramentas de IA</h3>
          <div className="grid grid-cols-2 gap-2">
            <label className="flex flex-col items-center justify-center p-4 bg-white rounded-xl border cursor-pointer hover:border-pati-orange">
              <span className="text-2xl mb-1">📸</span>
              <span className="text-xs font-medium">Ler Foto</span>
              <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
            </label>
            <button onClick={() => {}} className="flex flex-col items-center justify-center p-4 bg-white rounded-xl border hover:border-pati-orange"
              onClick={() => { const url = prompt('Cole o link do vídeo (YouTube/Instagram):'); if(url) {setVideoUrl(url); handleVideoTranscribe();} }}
            >
              <span className="text-2xl mb-1">🎥</span>
              <span className="text-xs font-medium">Ler Vídeo</span>
            </button>
          </div>

          <div className="space-y-2 mt-4 pt-4 border-t">
             <h4 className="text-xs font-bold text-gray-500 uppercase">O que cozinhar com o que tenho?</h4>
             <input 
               type="text" 
               placeholder="Ex: frango, tomate, creme de leite"
               className="w-full p-2 border rounded-lg text-sm"
               value={suggestionInput}
               onChange={e => setSuggestionInput(e.target.value)}
             />
             <button onClick={handleGetSuggestions} className="text-xs bg-pati-orange text-white px-3 py-2 rounded-lg">Pedir Sugestões</button>
             {suggestions && <div className="text-xs text-gray-600 bg-white p-3 rounded-lg border italic whitespace-pre-wrap mt-2">{suggestions}</div>}
          </div>
        </div>
      )}

      {/* Manual Fields */}
      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Nome da Receita</label>
          <input 
            type="text" 
            className="w-full p-3 border rounded-xl"
            value={formData.title}
            onChange={e => setFormData({ ...formData, title: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Categoria</label>
          <select 
            className="w-full p-3 border rounded-xl bg-white"
            value={formData.category}
            onChange={e => setFormData({ ...formData, category: e.target.value as any })}
          >
            {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Receita de quem? (Chef)</label>
          <input 
            type="text" 
            className="w-full p-3 border rounded-xl"
            value={formData.authorName}
            onChange={e => setFormData({ ...formData, authorName: e.target.value })}
            placeholder="Nome de quem criou/mandou"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Ingredientes</label>
          <textarea 
            className="w-full p-3 border rounded-xl h-32"
            value={formData.ingredients}
            onChange={e => setFormData({ ...formData, ingredients: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Modo de Preparo</label>
          <textarea 
            className="w-full p-3 border rounded-xl h-48"
            value={formData.instructions}
            onChange={e => setFormData({ ...formData, instructions: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Link do Vídeo (Opcional)</label>
          <input 
            type="text" 
            className="w-full p-3 border rounded-xl"
            value={formData.externalLink}
            onChange={e => setFormData({ ...formData, externalLink: e.target.value })}
          />
        </div>

        <div className="flex gap-3 pt-4">
          <button onClick={onCancel} className="flex-1 py-4 border rounded-xl font-bold text-gray-500">Cancelar</button>
          <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-xl font-bold shadow-lg">Salvar Receita</button>
        </div>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { AppView, Profile, Recipe } from './types';
import { FAMILY_PASSWORD, LOGO_URL, ICON_URL, CATEGORIES } from './constants';
import { gemini } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.LOGIN);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [activeProfile, setActiveProfile] = useState<Profile | null>(null);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');

  // Login State
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);

  // Profile Create State
  const [newProfileName, setNewProfileName] = useState('');
  const [newProfilePhoto, setNewProfilePhoto] = useState('');
  const [newProfileBirth, setNewProfileBirth] = useState('');

  // Recipe Form State
  const [editingRecipe, setEditingRecipe] = useState<Recipe | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Persistence
  useEffect(() => {
    const savedProfiles = localStorage.getItem('pati_profiles');
    const savedRecipes = localStorage.getItem('pati_recipes');
    if (savedProfiles) setProfiles(JSON.parse(savedProfiles));
    if (savedRecipes) setRecipes(JSON.parse(savedRecipes));
  }, []);

  useEffect(() => {
    localStorage.setItem('pati_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    localStorage.setItem('pati_recipes', JSON.stringify(recipes));
  }, [recipes]);

  const handleLogin = () => {
    if (passwordInput === FAMILY_PASSWORD) {
      setView(AppView.PROFILE_SELECT);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 2000);
    }
  };

  const handleAddProfile = () => {
    if (!newProfileName) return;
    const newProfile: Profile = {
      id: Date.now().toString(),
      name: newProfileName,
      photoUrl: newProfilePhoto || 'https://picsum.photos/200',
      birthDate: newProfileBirth,
    };
    setProfiles([...profiles, newProfile]);
    setView(AppView.PROFILE_SELECT);
    setNewProfileName('');
    setNewProfilePhoto('');
    setNewProfileBirth('');
  };

  const saveRecipe = (recipeData: Partial<Recipe>) => {
    if (editingRecipe) {
      setRecipes(recipes.map(r => r.id === editingRecipe.id ? { ...r, ...recipeData } as Recipe : r));
    } else {
      const newRecipe: Recipe = {
        id: Date.now().toString(),
        createdAt: Date.now(),
        authorId: activeProfile?.id || 'anonymous',
        authorName: activeProfile?.name || 'Visitante',
        title: recipeData.title || 'Sem título',
        category: recipeData.category || 'outros',
        ingredients: recipeData.ingredients || '',
        instructions: recipeData.instructions || '',
        externalLink: recipeData.externalLink,
        imageUrl: recipeData.imageUrl,
      };
      setRecipes([newRecipe, ...recipes]);
    }
    setEditingRecipe(null);
    setView(AppView.HOME);
  };

  const deleteRecipe = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir esta receita preciosa?')) {
      setRecipes(recipes.filter(r => r.id !== id));
      setView(AppView.HOME);
    }
  };

  // Views rendering
  if (view === AppView.LOGIN) {
    return (
      <div className="min-h-screen bg-pati-orange flex flex-col items-center justify-center p-6 text-white">
        <img src={LOGO_URL} alt="Logo" className="w-48 h-48 rounded-full border-4 border-white mb-8 shadow-xl" />
        <h1 className="text-4xl font-cursive mb-12">Caderno de receitas da Pati</h1>
        <div className="w-full max-w-sm space-y-4">
          <div className="relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔒</span>
            <input 
              type="password" 
              placeholder="Digite a senha da família" 
              className="w-full py-4 pl-12 pr-4 rounded-2xl text-gray-800 outline-none focus:ring-2 focus:ring-orange-300"
              value={passwordInput}
              onChange={(e) => setPasswordInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
            />
          </div>
          <button 
            onClick={handleLogin}
            className="w-full py-4 bg-white text-pati-orange font-bold rounded-2xl shadow-lg hover:bg-orange-50 active:scale-95 transition-all uppercase tracking-wider"
          >
            Entrar na Cozinha
          </button>
          {loginError && <p className="text-center text-sm font-medium">Senha incorreta, tente novamente!</p>}
        </div>
      </div>
    );
  }

  if (view === AppView.PROFILE_SELECT) {
    return (
      <div className="min-h-screen bg-white p-6 flex flex-col items-center">
        <img src={ICON_URL} alt="Logo" className="w-24 mb-6" />
        <p className="text-center text-gray-600 italic mb-8 px-4">
          "Nosso caderno de receitas virou app! Agora a gente compartilha segredos de cozinha, 
          fotografa caderninhos antigos e deixa tudo guardado aqui — com direito a 'assinatura' de quem mandou a receita. 
          Vamos cozinhar juntas, mesmo de longe?"
        </p>
        <h2 className="text-2xl font-cursive text-gray-800 mb-12">Quem está cozinhando hoje?</h2>

        <div className="grid grid-cols-2 gap-8 w-full max-w-md">
          {profiles.map(p => (
            <button key={p.id} onClick={() => { setActiveProfile(p); setView(AppView.HOME); }} className="flex flex-col items-center group">
              <img src={p.photoUrl} className="w-24 h-24 rounded-full border-2 border-transparent group-hover:border-pati-orange shadow-md object-cover mb-2" />
              <span className="font-medium text-gray-700">{p.name}</span>
            </button>
          ))}
          <button onClick={() => setView(AppView.PROFILE_CREATE)} className="flex flex-col items-center group">
            <div className="w-24 h-24 rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-3xl text-gray-300 group-hover:text-pati-orange group-hover:border-pati-orange">
              👤+
            </div>
            <span className="font-medium text-gray-400 mt-2">Novo Perfil</span>
          </button>
        </div>
      </div>
    );
  }

  if (view === AppView.PROFILE_CREATE) {
    return (
      <div className="min-h-screen bg-gray-50 p-6 flex flex-col">
        <button onClick={() => setView(AppView.PROFILE_SELECT)} className="text-pati-orange mb-6 flex items-center gap-2">← Voltar</button>
        <h2 className="text-2xl font-bold text-gray-800 mb-6">Criar Perfil de Família</h2>
        <div className="bg-white p-6 rounded-2xl shadow-sm space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">Nome Completo</label>
            <input 
              type="text" 
              className="w-full p-3 border rounded-xl"
              value={newProfileName}
              onChange={e => setNewProfileName(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">URL da Foto</label>
            <input 
              type="text" 
              placeholder="Link da imagem ou deixe em branco"
              className="w-full p-3 border rounded-xl"
              value={newProfilePhoto}
              onChange={e => setNewProfilePhoto(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">Data de Nascimento</label>
            <input 
              type="date" 
              className="w-full p-3 border rounded-xl"
              value={newProfileBirth}
              onChange={e => setNewProfileBirth(e.target.value)}
            />
          </div>
          <button onClick={handleAddProfile} className="w-full py-4 bg-pati-orange text-white rounded-xl font-bold shadow-lg">Criar Perfil</button>
        </div>
      </div>
    );
  }

  const filteredRecipes = recipes.filter(r => {
    const matchesSearch = r.title.toLowerCase().includes(search.toLowerCase()) || r.ingredients.toLowerCase().includes(search.toLowerCase());
    const matchesCategory = categoryFilter === 'all' || r.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      {/* Header */}
      <header className="bg-white p-4 shadow-sm sticky top-0 z-20 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <img src={ICON_URL} alt="Icon" className="w-10 h-10" />
          <h1 className="text-xl font-cursive text-pati-orange">chef.ai da Pati</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView(AppView.AI_TOOLS)} className="text-2xl" title="Sugestões da IA">🪄</button>
          <img 
            src={activeProfile?.photoUrl} 
            className="w-10 h-10 rounded-full border border-pati-orange cursor-pointer object-cover" 
            onClick={() => setView(AppView.PROFILE_SELECT)}
          />
        </div>
      </header>

      {/* Content */}
      <div className="p-4 max-w-2xl mx-auto">
        {view === AppView.HOME && (
          <>
            <div className="mb-6 space-y-4">
              <input 
                type="text" 
                placeholder="🔍 Buscar receitas..." 
                className="w-full p-3 rounded-2xl border-none shadow-sm focus:ring-2 focus:ring-pati-orange"
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
              <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                <button 
                  onClick={() => setCategoryFilter('all')}
                  className={`px-4 py-2 rounded-full whitespace-nowrap text-sm font-medium transition-colors ${categoryFilter === 'all' ? 'bg-pati-orange text-white' : 'bg-white text-gray-600'}`}
                >
                  Todas
                </button>
                {CATEGORIES.map(cat => (
                  <button 
                    key={cat.id}
                    onClick={() => setCategoryFilter(cat.id)}
                    className={`px-4 py-2 rounded-full whitespace-nowrap text-sm font-medium transition-colors ${categoryFilter === cat.id ? 'bg-pati-orange text-white' : 'bg-white text-gray-600 shadow-sm'}`}
                  >
                    {cat.icon} {cat.label}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              {filteredRecipes.length === 0 ? (
                <div className="text-center py-20 text-gray-400">
                  <p className="text-4xl mb-4">🥘</p>
                  <p>Nenhuma receita encontrada.</p>
                  <p className="text-sm">Que tal adicionar uma nova?</p>
                </div>
              ) : (
                filteredRecipes.map(recipe => (
                  <div key={recipe.id} className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 group transition-all" onClick={() => { setEditingRecipe(recipe); setView(AppView.RECIPE_DETAIL); }}>
                    {recipe.imageUrl && (
                      <img src={recipe.imageUrl} className="w-full h-40 object-cover" />
                    )}
                    <div className="p-4">
                      <div className="flex justify-between items-start mb-2">
                        <span className="text-xs font-bold uppercase tracking-wider text-pati-orange bg-orange-50 px-2 py-1 rounded">
                          {CATEGORIES.find(c => c.id === recipe.category)?.label}
                        </span>
                        <span className="text-xs text-gray-400">
                          {new Date(recipe.createdAt).toLocaleDateString('pt-BR')}
                        </span>
                      </div>
                      <h3 className="text-lg font-bold text-gray-800 mb-1">{recipe.title}</h3>
                      <p className="text-sm text-gray-500 mb-4 line-clamp-2">{recipe.ingredients}</p>
                      <div className="flex justify-between items-center border-t pt-3 mt-auto">
                        <span className="text-xs text-gray-600 italic">Chef: {recipe.authorName}</span>
                        {recipe.externalLink && <span className="text-xs text-blue-500">🔗 Vídeo</span>}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </>
        )}

        {(view === AppView.RECIPE_DETAIL && editingRecipe) && (
          <div className="bg-white rounded-3xl p-6 shadow-lg min-h-[80vh]">
            <div className="flex justify-between mb-4">
               <button onClick={() => setView(AppView.HOME)} className="text-pati-orange font-bold">← Voltar</button>
               <div className="flex gap-4">
                 <button onClick={() => setView(AppView.RECIPE_EDIT)} className="text-gray-400">✏️</button>
                 <button onClick={() => deleteRecipe(editingRecipe.id)} className="text-red-300">🗑️</button>
               </div>
            </div>

            {editingRecipe.imageUrl && <img src={editingRecipe.imageUrl} className="w-full h-56 object-cover rounded-2xl mb-6" />}

            <h2 className="text-3xl font-cursive text-gray-800 mb-2">{editingRecipe.title}</h2>
            <div className="flex items-center gap-2 mb-6">
              <span className="px-3 py-1 bg-orange-100 text-pati-orange rounded-full text-xs font-bold uppercase">{editingRecipe.category}</span>
              <span className="text-sm text-gray-400">Por {editingRecipe.authorName}</span>
            </div>

            <div className="space-y-6">
              <section>
                <h4 className="font-bold text-gray-700 mb-2 border-l-4 border-pati-orange pl-3">Ingredientes</h4>
                <p className="text-gray-600 whitespace-pre-wrap leading-relaxed">{editingRecipe.ingredients}</p>
              </section>

              <section>
                <h4 className="font-bold text-gray-700 mb-2 border-l-4 border-pati-orange pl-3">Modo de Preparo</h4>
                <p className="text-gray-600 whitespace-pre-wrap leading-relaxed">{editingRecipe.instructions}</p>
              </section>

              {editingRecipe.externalLink && (
                <section>
                  <h4 className="font-bold text-gray-700 mb-2 border-l-4 border-pati-orange pl-3">Link do Vídeo</h4>
                  <a href={editingRecipe.externalLink} target="_blank" rel="noopener noreferrer" className="text-blue-500 break-all underline">
                    {editingRecipe.externalLink}
                  </a>
                </section>
              )}
            </div>
          </div>
        )}

        {(view === AppView.RECIPE_EDIT || view === AppView.AI_TOOLS) && (
          <RecipeForm 
            recipe={editingRecipe || undefined} 
            activeProfile={activeProfile}
            onSave={saveRecipe} 
            onCancel={() => setView(AppView.HOME)} 
            isAiLoading={isAiLoading}
            setIsAiLoading={setIsAiLoading}
          />
        )}
      </div>

      {/* Floating Add Button */}
      {view === AppView.HOME && (
        <button 
          onClick={() => { setEditingRecipe(null); setView(AppView.RECIPE_EDIT); }}
          className="fixed bottom-6 right-6 w-16 h-16 bg-pati-orange text-white text-3xl rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-50"
        >
          +
        </button>
      )}
    </div>
  );
};

interface RecipeFormProps {
  recipe?: Recipe;
  activeProfile: Profile | null;
  onSave: (data: Partial<Recipe>) => void;
  onCancel: () => void;
  isAiLoading: boolean;
  setIsAiLoading: (v: boolean) => void;
}

const RecipeForm: React.FC<RecipeFormProps> = ({ recipe, activeProfile, onSave, onCancel, isAiLoading, setIsAiLoading }) => {
  const [formData, setFormData] = useState<Partial<Recipe>>(recipe || {
    title: '',
    category: 'outros',
    ingredients: '',
    instructions: '',
    externalLink: '',
    imageUrl: '',
    authorName: activeProfile?.name || ''
  });
  const [videoUrl, setVideoUrl] = useState('');
  const [suggestionInput, setSuggestionInput] = useState('');
  const [suggestions, setSuggestions] = useState('');

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsAiLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const result = await gemini.transcribeImage(base64);
        setFormData(prev => ({ ...prev, ...result, imageUrl: reader.result as string }));
      } catch (err) {
        alert('Erro ao transcrever imagem. Verifique sua conexão ou API Key.');
      } finally {
        setIsAiLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleVideoTranscribe = async () => {
    if (!videoUrl) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.transcribeVideoLink(videoUrl);
      setFormData(prev => ({ ...prev, ...result, externalLink: videoUrl }));
    } catch (err) {
      alert('A IA não conseguiu transcrever este vídeo automaticamente, mas salvamos o link para você!');
      setFormData(prev => ({ ...prev, externalLink: videoUrl }));
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleGetSuggestions = async () => {
    if (!suggestionInput) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.getRecipeSuggestions(suggestionInput);
      setSuggestions(result || 'Nenhuma sugestão encontrada.');
    } catch (err) {
      alert('Erro ao buscar sugestões.');
    } finally {
      setIsAiLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-3xl p-6 shadow-sm space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">{recipe ? 'Editar Receita' : 'Nova Receita'}</h2>
        <button onClick={onCancel} className="text-gray-400">Fechar</button>
      </div>

      {isAiLoading && (
        <div className="bg-orange-50 p-4 rounded-xl border border-orange-200 animate-pulse text-center">
          <p className="text-pati-orange font-medium">👨‍🍳 Chef.AI está trabalhando na sua receita...</p>
        </div>
      )}

      {/* AI Tools Section */}
      {!recipe && (
        <div className="bg-gray-50 p-4 rounded-2xl space-y-4">
          <h3 className="text-sm font-bold text-gray-500 uppercase">Ferramentas de IA</h3>
          <div className="grid grid-cols-2 gap-2">
            <label className="flex flex-col items-center justify-center p-4 bg-white rounded-xl border cursor-pointer hover:border-pati-orange">
              <span className="text-2xl mb-1">📸</span>
              <span className="text-xs font-medium">Ler Foto</span>
              <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
            </label>
            {/* FIX: Removed duplicate onClick attribute */}
            <button 
              className="flex flex-col items-center justify-center p-4 bg-white rounded-xl border hover:border-pati-orange"
              onClick={() => { const url = prompt('Cole o link do vídeo (YouTube/Instagram):'); if(url) {setVideoUrl(url); handleVideoTranscribe();} }}
            >
              <span className="text-2xl mb-1">🎥</span>
              <span className="text-xs font-medium">Ler Vídeo</span>
            </button>
          </div>

          <div className="space-y-2 mt-4 pt-4 border-t">
             <h4 className="text-xs font-bold text-gray-500 uppercase">O que cozinhar com o que tenho?</h4>
             <input 
               type="text" 
               placeholder="Ex: frango, tomate, creme de leite"
               className="w-full p-2 border rounded-lg text-sm"
               value={suggestionInput}
               onChange={e => setSuggestionInput(e.target.value)}
             />
             <button onClick={handleGetSuggestions} className="text-xs bg-pati-orange text-white px-3 py-2 rounded-lg">Pedir Sugestões</button>
             {suggestions && <div className="text-xs text-gray-600 bg-white p-3 rounded-lg border italic whitespace-pre-wrap mt-2">{suggestions}</div>}
          </div>
        </div>
      )}

      {/* Manual Fields */}
      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Nome da Receita</label>
          <input 
            type="text" 
            className="w-full p-3 border rounded-xl"
            value={formData.title}
            onChange={e => setFormData({ ...formData, title: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Categoria</label>
          <select 
            className="w-full p-3 border rounded-xl bg-white"
            value={formData.category}
            onChange={e => setFormData({ ...formData, category: e.target.value as any })}
          >
            {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Receita de quem? (Chef)</label>
          <input 
            type="text" 
            className="w-full p-3 border rounded-xl"
            value={formData.authorName}
            onChange={e => setFormData({ ...formData, authorName: e.target.value })}
            placeholder="Nome de quem criou/mandou"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Ingredientes</label>
          <textarea 
            className="w-full p-3 border rounded-xl h-32"
            value={formData.ingredients}
            onChange={e => setFormData({ ...formData, ingredients: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Modo de Preparo</label>
          <textarea 
            className="w-full p-3 border rounded-xl h-48"
            value={formData.instructions}
            onChange={e => setFormData({ ...formData, instructions: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-600 mb-1">Link do Vídeo (Opcional)</label>
          <input 
            type="text" 
            className="w-full p-3 border rounded-xl"
            value={formData.externalLink}
            onChange={e => setFormData({ ...formData, externalLink: e.target.value })}
          />
        </div>

        <div className="flex gap-3 pt-4">
          <button onClick={onCancel} className="flex-1 py-4 border rounded-xl font-bold text-gray-500">Cancelar</button>
          <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-xl font-bold shadow-lg">Salvar Receita</button>
        </div>
      </div>
    </div>
  );
};

