import { GoogleGenAI, Type } from "@google/genai";

export class GeminiService {
  // Removed static initialization and private ai property to ensure fresh instances with latest API Key.

  async transcribeImage(base64Image: string) {
    // FIX: Instantiate GoogleGenAI right before use as per guidelines.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: "image/jpeg" } },
          { text: "Você é um assistente de cozinha experiente. Transcreva esta imagem de uma receita (pode ser escrita à mão) para um formato JSON estruturado com os campos: title, ingredients, instructions e category (escolha entre: entradas, salgados, sobremesas, bebidas, outros). Responda apenas o JSON." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async transcribeVideoLink(url: string) {
    // FIX: Instantiate GoogleGenAI right before use as per guidelines.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Extraia a receita completa deste vídeo: ${url}. Pesquise o conteúdo se necessário para garantir fidelidade. Retorne em formato JSON com: title, ingredients, instructions e category (entradas, salgados, sobremesas, bebidas, outros).`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async getRecipeSuggestions(ingredients: string) {
    // FIX: Instantiate GoogleGenAI right before use as per guidelines.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Com base nestes ingredientes: ${ingredients}, sugira 3 receitas criativas que eu possa fazer. Para cada receita, forneça nome, uma breve descrição e por que combina com os ingredientes.`,
    });

    return response.text;
  }
}

