              <span className="text-[10px] text-gray-400 uppercase mt-1">Instagram ou YouTube</span>
            </button>
          </div>

          <div className="space-y-3 pt-4 border-t border-gray-200">
             <h4 className="text-xs font-bold text-gray-500 uppercase">O que cozinhar com o que tenho?</h4>
             <div className="flex gap-2">
                <input 
                    type="text" 
                    placeholder="Ex: frango, tomate, creme de leite"
                    className="flex-1 p-3 border rounded-xl text-sm outline-none focus:ring-2 focus:ring-pati-orange shadow-inner"
                    value={suggestionInput}
                    onChange={e => setSuggestionInput(e.target.value)}
                />
                <button onClick={handleGetSuggestions} className="bg-pati-orange text-white px-4 py-2 rounded-xl font-bold text-xs uppercase shadow-md hover:bg-orange-600">Sugerir</button>
             </div>
             {suggestions && <div className="text-xs text-gray-600 bg-white p-4 rounded-xl border-l-4 border-pati-orange italic whitespace-pre-wrap shadow-sm">{suggestions}</div>}
          </div>
        </div>
      )}

      {/* Manual Fields */}
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Título da Receita</label>
