            </div>
            <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Categoria</label>
                <select 
                    className="w-full p-4 border rounded-xl bg-white focus:border-pati-orange outline-none shadow-sm cursor-pointer"
