            </div>
        </div>

        <div>
          <label className="block text-sm font-bold text-gray-700 mb-2">Receita de quem? (O Chef/Dono)</label>
          <input 
            type="text" 
            className="w-full p-4 border rounded-xl focus:border-pati-orange outline-none shadow-sm transition-colors"
            value={formData.authorName}
            onChange={e => setFormData({ ...formData, authorName: e.target.value })}
            placeholder="Nome de quem criou ou compartilhou a receita"
          />
        </div>

        <div>
          <label className="block text-sm font-bold text-gray-700 mb-2">Ingredientes</label>
          <textarea 
            className="w-full p-4 border rounded-xl h-40 focus:border-pati-orange outline-none shadow-sm transition-colors resize-none leading-relaxed"
            value={formData.ingredients}
            placeholder="Liste os ingredientes aqui..."
            onChange={e => setFormData({ ...formData, ingredients: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-bold text-gray-700 mb-2">Modo de Preparo</label>
          <textarea 
            className="w-full p-4 border rounded-xl h-60 focus:border-pati-orange outline-none shadow-sm transition-colors resize-none leading-relaxed"
            value={formData.instructions}
            placeholder="Explique o passo a passo..."
            onChange={e => setFormData({ ...formData, instructions: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-bold text-gray-700 mb-2">Link do Vídeo ou Referência</label>
          <input 
            type="text" 
            className="w-full p-4 border rounded-xl focus:border-pati-orange outline-none shadow-sm transition-colors"
            value={formData.externalLink}
            placeholder="https://..."
            onChange={e => setFormData({ ...formData, externalLink: e.target.value })}
          />
        </div>

        <div className="flex gap-4 pt-6">
          <button onClick={onCancel} className="flex-1 py-4 border-2 border-gray-100 rounded-2xl font-bold text-gray-400 hover:bg-gray-50 transition-colors">Cancelar</button>
          <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-2xl font-bold shadow-xl hover:bg-orange-600 transform active:scale-95 transition-all">Salvar no Caderno</button>
        </div>
      </div>
    </div>
  );
};

