import { GoogleGenAI, Type } from "@google/genai";

export class GeminiService {
  async transcribeImage(base64Image: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: "image/jpeg" } },
          { text: "Você é um assistente de cozinha experiente. Transcreva esta imagem de uma receita para um formato JSON estruturado com os campos: title, ingredients, instructions e category (escolha entre: entradas, saladas, prato_principal, massas, salgados, sobremesas, bebidas, outros). Responda apenas o JSON." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async transcribeVideoLink(url: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Extraia a receita completa deste vídeo: ${url}. Retorne em formato JSON com: title, ingredients, instructions e category (entradas, saladas, prato_principal, massas, salgados, sobremesas, bebidas, outros).`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async getRecipeSuggestions(ingredients: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Com base nestes ingredientes: ${ingredients}, sugira UMA única receita criativa. Retorne no formato JSON: title, ingredients, instructions e category (entradas, saladas, prato_principal, massas, salgados, sobremesas, bebidas, outros).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }
}

