interface RecipeFormProps {
  recipe?: Recipe;
  activeProfile: Profile | null;
  onSave: (data: Partial<Recipe>) => void;
  onCancel: () => void;
  isAiLoading: boolean;
  setIsAiLoading: (v: boolean) => void;
}

const RecipeForm: React.FC<RecipeFormProps> = ({ recipe, activeProfile, onSave, onCancel, isAiLoading, setIsAiLoading }) => {
  const [formData, setFormData] = useState<Partial<Recipe>>(recipe || {
    title: '',
    category: 'outros',
    ingredients: '',
    instructions: '',
    externalLink: '',
    imageUrl: '',
    authorName: activeProfile?.name || ''
  });
  const [videoUrl, setVideoUrl] = useState('');
  const [suggestionInput, setSuggestionInput] = useState('');
  const [suggestion, setSuggestion] = useState<any>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsAiLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const result = await gemini.transcribeImage(base64);
        setFormData(prev => ({ ...prev, ...result, imageUrl: reader.result as string }));
      } catch (err) {
        alert('Erro ao transcrever imagem. Verifique sua conexão ou API Key.');
      } finally {
        setIsAiLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleManualImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => {
              setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
          };
          reader.readAsDataURL(file);
      }
  };

  const handleVideoTranscribe = async () => {
    if (!videoUrl) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.transcribeVideoLink(videoUrl);
      setFormData(prev => ({ ...prev, ...result, externalLink: videoUrl }));
    } catch (err) {
      alert('A IA não conseguiu transcrever este vídeo automaticamente, mas salvamos o link para você!');
      setFormData(prev => ({ ...prev, externalLink: videoUrl }));
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleGetSuggestions = async () => {
    if (!suggestionInput) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.getRecipeSuggestions(suggestionInput);
      setSuggestion(result);
    } catch (err) {
      alert('Erro ao buscar sugestões.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleSaveSuggested = () => {
      if (suggestion) {
          setFormData(prev => ({
              ...prev,
              title: suggestion.title,
              ingredients: suggestion.ingredients,
              instructions: suggestion.instructions,
              category: suggestion.category
          }));
          setSuggestion(null);
      }
  };

  return (
    <div className="bg-white rounded-3xl p-8 shadow-lg space-y-8 max-w-3xl mx-auto border border-gray-100">
      <div className="flex justify-between items-center border-b border-gray-50 pb-4">
        <h2 className="text-2xl font-bold text-gray-800">{recipe ? 'Editar Receita' : 'Nova Receita'}</h2>
        <button onClick={onCancel} className="text-gray-400 hover:text-gray-600 p-2">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
        </button>
      </div>

      {isAiLoading && (
        <div className="bg-orange-50 p-6 rounded-2xl border-2 border-dashed border-pati-orange animate-pulse text-center">
          <p className="text-pati-orange font-bold text-lg">👨‍🍳 Chef.AI está cozinhando...</p>
          <p className="text-xs text-orange-400 uppercase tracking-widest mt-1">Isso pode levar alguns segundos</p>
        </div>
      )}

      {/* AI Tools Section */}
      {!recipe && (
        <div className="bg-gray-50 p-6 rounded-3xl space-y-6">
          <h3 className="text-xs font-extrabold text-gray-400 uppercase tracking-widest">Ajudantes da Pati (IA)</h3>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <label className="flex flex-col items-center justify-center p-6 bg-white rounded-2xl border-2 border-dashed border-gray-200 cursor-pointer hover:border-pati-orange hover:bg-orange-50 transition-all group">
              <span className="text-4xl mb-2 group-hover:scale-110 transition-transform">📸</span>
              <span className="text-sm font-bold text-gray-700">Digitalizar Receita</span>
              <span className="text-[10px] text-gray-400 uppercase mt-1 text-center leading-tight">Transcreve cadernos<br/>ou fotos</span>
              <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
            </label>

            <div className="flex flex-col p-6 bg-white rounded-2xl border-2 border-dashed border-gray-200 hover:border-pati-orange hover:bg-orange-50 transition-all space-y-3">
              <div className="flex flex-col items-center text-center">
                <span className="text-4xl mb-2">🎥</span>
                <span className="text-sm font-bold text-gray-700">Importar Vídeo</span>
              </div>
              <input 
                type="text" 
                placeholder="Cole o link do vídeo..."
                className="w-full p-2 text-xs border rounded-lg outline-none focus:ring-1 focus:ring-pati-orange"
                value={videoUrl}
                onChange={e => setVideoUrl(e.target.value)}
              />
              <button 
                onClick={handleVideoTranscribe}
                className="bg-pati-orange text-white py-2 rounded-lg font-bold text-[10px] uppercase shadow hover:bg-orange-600 disabled:opacity-50"
                disabled={!videoUrl || isAiLoading}
              >
                Transcrever Vídeo
              </button>
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-gray-200">
             <div className="flex flex-col">
                 <h4 className="text-xs font-bold text-gray-500 uppercase tracking-tight mb-2">O que cozinhar com o que tenho em casa?</h4>
                 <div className="flex gap-2">
                    <input 
                        type="text" 
                        placeholder="Ex: frango, tomate, creme de leite"
                        className="flex-1 p-3 border rounded-xl text-sm outline-none focus:ring-2 focus:ring-pati-orange shadow-inner bg-white"
                        value={suggestionInput}
                        onChange={e => setSuggestionInput(e.target.value)}
                    />
                    <button onClick={handleGetSuggestions} className="bg-pati-orange text-white px-5 py-2 rounded-xl font-bold text-xs uppercase shadow-md hover:bg-orange-600 disabled:opacity-50" disabled={isAiLoading}>Pedir Dica</button>
                 </div>
             </div>

             {suggestion && (
                 <div className="bg-white p-5 rounded-2xl border-2 border-pati-orange shadow-lg space-y-4">
                    <div className="flex justify-between items-start">
                        <h5 className="font-bold text-gray-800 text-lg">{suggestion.title}</h5>
                        <span className="text-[10px] bg-orange-100 text-pati-orange px-2 py-1 rounded-full font-bold uppercase">{CATEGORIES.find(c => c.id === suggestion.category)?.label || suggestion.category}</span>
                    </div>
                    <div className="text-sm text-gray-600">
                        <p className="font-bold text-xs uppercase text-gray-400 mb-1">Ingredientes:</p>
                        <p className="line-clamp-3 italic">{suggestion.ingredients}</p>
                    </div>
                    <div className="flex gap-2 pt-2">
                        <button onClick={handleGetSuggestions} className="flex-1 py-2 border border-pati-orange text-pati-orange rounded-xl text-xs font-bold hover:bg-orange-50">Refazer 🔄</button>
                        <button onClick={handleSaveSuggested} className="flex-[2] py-2 bg-pati-orange text-white rounded-xl text-xs font-bold shadow hover:bg-orange-600">Salvar no Caderno ✅</button>
                    </div>
                 </div>
             )}
          </div>
        </div>
      )}

      {/* Manual Fields */}
      <div className="space-y-6">
        <div className="flex flex-col items-center">
            <div className="w-full h-56 rounded-3xl bg-gray-50 border-2 border-dashed border-gray-200 overflow-hidden relative group">
                {formData.imageUrl ? (
                    <img src={formData.imageUrl} className="w-full h-full object-cover" />
                ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-gray-300">
                        <span className="text-5xl mb-2">🥘</span>
                        <span className="text-sm font-bold">Sem Foto</span>
                    </div>
                )}
                <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                    <span className="text-white font-bold text-sm bg-pati-orange px-4 py-2 rounded-full shadow-lg cursor-pointer">Trocar Foto</span>
                </div>
                <input 
                    type="file" 
                    accept="image/*" 
                    className="absolute inset-0 opacity-0 cursor-pointer" 
                    onChange={handleManualImageUpload}
                />
            </div>
            <p className="text-[10px] text-gray-400 uppercase mt-2 font-bold">Toque na imagem para editar a foto da receita</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Título da Receita</label>
                <input 
                    type="text" 
                    className="w-full p-4 border rounded-xl focus:border-pati-orange outline-none shadow-sm transition-colors"
                    value={formData.title}
                    placeholder="Ex: Bolo de Fubá da Vovó"
                    onChange={e => setFormData({ ...formData, title: e.target.value })}
                />
            </div>
            <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Categoria</label>
                <select 
                    className="w-full p-4 border rounded-xl bg-white focus:border-pati-orange outline-none shadow-sm cursor-pointer"
                    value={formData.category}
                    onChange={e => setFormData({ ...formData, category: e.target.value as any })}
                >
                    {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.icon} {c.label}</option>)}
                </select>
            </div>
        </div>

        <div>
          <label className="block text-sm font-bold text-gray-700 mb-2">Receita de quem? (O Chef/Dono)</label>
          <input 
            type="text" 
            className="w-full p-4 border rounded-xl focus:border-pati-orange outline-none shadow-sm transition-colors"
            value={formData.authorName}
            onChange={e => setFormData({ ...formData, authorName: e.target.value })}
            placeholder="Nome de quem criou ou compartilhou a receita"
          />
        </div>

        <div>
          <label className="block text-sm font-bold text-gray-700 mb-2">Ingredientes</label>
          <textarea 
            className="w-full p-4 border rounded-xl h-40 focus:border-pati-orange outline-none shadow-sm transition-colors resize-none leading-relaxed"
            value={formData.ingredients}
            placeholder="Liste os ingredientes aqui..."
            onChange={e => setFormData({ ...formData, ingredients: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-bold text-gray-700 mb-2">Modo de Preparo</label>
          <textarea 
            className="w-full p-4 border rounded-xl h-60 focus:border-pati-orange outline-none shadow-sm transition-colors resize-none leading-relaxed"
            value={formData.instructions}
            placeholder="Explique o passo a passo..."
            onChange={e => setFormData({ ...formData, instructions: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-sm font-bold text-gray-700 mb-2">Link do Vídeo ou Referência</label>
          <input 
            type="text" 
            className="w-full p-4 border rounded-xl focus:border-pati-orange outline-none shadow-sm transition-colors"
            value={formData.externalLink}
            placeholder="https://..."
            onChange={e => setFormData({ ...formData, externalLink: e.target.value })}
          />
        </div>

        <div className="flex gap-4 pt-6">
          <button onClick={onCancel} className="flex-1 py-4 border-2 border-gray-100 rounded-2xl font-bold text-gray-400 hover:bg-gray-50 transition-colors">Cancelar</button>
          <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-2xl font-bold shadow-xl hover:bg-orange-600 transform active:scale-95 transition-all">Salvar no Caderno</button>
        </div>
      </div>
    </div>
  );
};

