          </div>
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Data de Nascimento</label>
            <input 
              type="date" 
              className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-pati-orange outline-none transition-colors"
