      r.title.toLowerCase().includes(searchLower) || 
      r.ingredients.toLowerCase().includes(searchLower) ||
      r.authorName.toLowerCase().includes(searchLower);
    const matchesCategory = categoryFilter === 'all' || r.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      {/* Header with Integrated Search */}
      <header className="bg-white p-4 shadow-md sticky top-0 z-40 flex flex-col border-b border-gray-100">
        <div className="flex justify-between items-center mb-3">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full border-2 border-pati-orange overflow-hidden shadow-sm">
              <img src={LOGO_URL} alt="Logo" className="w-full h-full object-cover" />
            </div>
            <h1 className="text-lg font-cursive text-pati-orange leading-tight">Caderno de receitas da Pati</h1>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setView(AppView.AI_TOOLS)} className="p-2 hover:bg-orange-50 rounded-full transition-colors" title="Sugestões da IA">
              <span className="text-2xl">🪄</span>
            </button>
            <img 
              src={activeProfile?.photoUrl} 
              className="w-10 h-10 rounded-full border-2 border-pati-orange cursor-pointer object-cover shadow-sm transform hover:scale-105 transition-transform" 
              onClick={() => setView(AppView.PROFILE_SELECT)}
            />
          </div>
        </div>

        {/* Universal Search Bar with Search Button */}
        {view === AppView.HOME && (
          <form onSubmit={handleSearchSubmit} className="relative w-full max-w-2xl mx-auto flex gap-2">
            <div className="relative flex-1">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔍</span>
              <input 
                type="text" 
                placeholder="Buscar por receita, ingrediente ou chef..." 
                className="w-full p-3 pl-12 rounded-2xl border border-gray-100 shadow-sm focus:ring-2 focus:ring-pati-orange bg-gray-50 text-sm outline-none"
                value={tempSearch}
                onChange={e => setTempSearch(e.target.value)}
              />
            </div>
            <button type="submit" className="bg-pati-orange text-white px-6 rounded-2xl font-bold text-xs uppercase shadow-sm hover:bg-orange-600 transition-colors">
              Buscar
            </button>
          </form>
        )}
      </header>

      {/* Content Layout with Vertical Menu */}
      <div className="p-4 max-w-6xl mx-auto flex flex-col md:flex-row gap-6">

        {/* Sidebar Vertical Menu - Visible only on Home */}
        {(view === AppView.HOME) && (
          <aside className="w-full md:w-64 space-y-4">
            <div className="bg-white p-2 rounded-2xl shadow-sm border border-gray-100 sticky top-40">
                <h3 className="p-3 text-xs font-bold text-gray-400 uppercase tracking-widest border-b border-gray-50 mb-2">Categorias</h3>
                <nav className="flex flex-col gap-1">
                    <button 
                        onClick={() => setCategoryFilter('all')}
                        className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all ${categoryFilter === 'all' ? 'bg-pati-orange text-white shadow-md' : 'text-gray-600 hover:bg-orange-50'}`}
                    >
                        <span>🍽️</span> Todas as Receitas
                    </button>
                    {CATEGORIES.map(cat => (
                        <button 
                            key={cat.id}
                            onClick={() => setCategoryFilter(cat.id)}
                            className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all ${categoryFilter === cat.id ? 'bg-pati-orange text-white shadow-md' : 'text-gray-600 hover:bg-orange-50'}`}
                        >
                            <span>{cat.icon}</span> {cat.label}
                        </button>
                    ))}
                </nav>
            </div>
          </aside>
        )}

        {/* Main Area */}
        <main className="flex-1 min-w-0">
            {view === AppView.HOME && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredRecipes.length === 0 ? (
                    <div className="col-span-full text-center py-24 text-gray-400 bg-white rounded-3xl shadow-sm border border-dashed border-gray-200">
                    <p className="text-5xl mb-4">🍳</p>
                    <p className="font-medium">Nenhuma receita encontrada para sua busca.</p>
                    <p className="text-sm mt-1">Limpe o filtro ou crie uma nova receita!</p>
                    </div>
                ) : (
                    filteredRecipes.map(recipe => (
                    <div key={recipe.id} className="bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl border border-gray-100 group transition-all cursor-pointer flex flex-col" onClick={() => { setEditingRecipe(recipe); setView(AppView.RECIPE_DETAIL); }}>
                        <div className="relative h-48 overflow-hidden">
                            {recipe.imageUrl ? (
                                <img src={recipe.imageUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110 duration-500" />
                            ) : (
                                <div className="w-full h-full bg-orange-50 flex items-center justify-center text-4xl">🥘</div>
                            )}
                            <div className="absolute top-3 left-3">
                                <span className="px-3 py-1 bg-white/90 backdrop-blur-sm text-pati-orange text-[10px] font-bold uppercase rounded-full shadow-sm">
                                    {CATEGORIES.find(c => c.id === recipe.category)?.label}
                                </span>
                            </div>
                        </div>
                        <div className="p-5 flex-1 flex flex-col">
                            <h3 className="text-xl font-bold text-gray-800 mb-2 group-hover:text-pati-orange transition-colors line-clamp-1">{recipe.title}</h3>
                            <p className="text-sm text-gray-500 mb-4 line-clamp-3 leading-relaxed flex-1">{recipe.ingredients}</p>
                            <div className="flex justify-between items-center border-t border-gray-50 pt-4 mt-auto">
                                <div className="flex items-center gap-2">
                                    <div className="w-6 h-6 rounded-full bg-pati-orange/10 flex items-center justify-center text-[10px] text-pati-orange font-bold uppercase overflow-hidden">
                                        {profiles.find(p => p.id === recipe.authorId)?.photoUrl ? (
                                          <img src={profiles.find(p => p.id === recipe.authorId)?.photoUrl} className="w-full h-full object-cover" />
                                        ) : recipe.authorName.charAt(0)}
                                    </div>
                                    <span className="text-[10px] text-gray-500 font-bold uppercase tracking-tighter">Chef: {recipe.authorName}</span>
                                </div>
                                {recipe.externalLink && <span className="text-[10px] bg-blue-50 text-blue-500 px-2 py-1 rounded font-bold">VÍDEO 🎬</span>}
                            </div>
                        </div>
                    </div>
                    ))
                )}
            </div>
            )}

            {(view === AppView.RECIPE_DETAIL && editingRecipe) && (
            <div className="bg-white rounded-3xl p-8 shadow-xl max-w-3xl mx-auto border border-gray-100">
                <div className="flex justify-between items-center mb-8">
                <button onClick={() => setView(AppView.HOME)} className="text-pati-orange font-bold flex items-center gap-2 hover:translate-x-[-4px] transition-transform">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7"/></svg>
                    Voltar
                </button>
                <div className="flex gap-4">
                    <button onClick={() => setView(AppView.RECIPE_EDIT)} className="p-2 hover:bg-gray-50 rounded-full transition-colors text-xl">✏️</button>
                    <button onClick={() => deleteRecipe(editingRecipe.id)} className="p-2 hover:bg-red-50 rounded-full transition-colors text-red-400 text-xl">🗑️</button>
                </div>
                </div>

                {editingRecipe.imageUrl && <img src={editingRecipe.imageUrl} className="w-full h-80 object-cover rounded-3xl mb-8 shadow-md" />}

                <h2 className="text-4xl font-cursive text-gray-800 mb-4">{editingRecipe.title}</h2>
                <div className="flex items-center gap-4 mb-8">
                <span className="px-4 py-1.5 bg-orange-100 text-pati-orange rounded-full text-xs font-extrabold uppercase tracking-widest">
                    {CATEGORIES.find(c => c.id === editingRecipe.category)?.label}
                </span>
                <span className="text-sm font-semibold text-gray-400">Receita de <span className="text-gray-700">{editingRecipe.authorName}</span></span>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                <section className="bg-orange-50/30 p-6 rounded-2xl border border-orange-50">
                    <h4 className="font-extrabold text-pati-orange text-xs uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                        <span className="text-xl">🥛</span> Ingredientes
                    </h4>
                    <p className="text-gray-700 whitespace-pre-wrap leading-loose text-sm font-medium">{editingRecipe.ingredients}</p>
                </section>

                <section className="p-6">
                    <h4 className="font-extrabold text-gray-400 text-xs uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                        <span className="text-xl">🔥</span> Modo de Preparo
                    </h4>
                    <p className="text-gray-700 whitespace-pre-wrap leading-relaxed text-sm">{editingRecipe.instructions}</p>
                </section>
                </div>

                {editingRecipe.externalLink && (
                <section className="mt-8 pt-8 border-t border-gray-100">
                    <h4 className="font-extrabold text-gray-400 text-xs uppercase tracking-widest mb-4">Link Original da Receita</h4>
                    <a href={editingRecipe.externalLink} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 px-6 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-sm hover:bg-blue-100 transition-colors break-all">
                        <span>🎬 Assistir vídeo da receita</span>
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/></svg>
                    </a>
                </section>
                )}
            </div>
            )}

            {(view === AppView.RECIPE_EDIT || view === AppView.AI_TOOLS) && (
            <RecipeForm 
                recipe={editingRecipe || undefined} 
                activeProfile={activeProfile}
                onSave={saveRecipe} 
                onCancel={() => setView(AppView.HOME)} 
                isAiLoading={isAiLoading}
                setIsAiLoading={setIsAiLoading}
            />
            )}
        </main>
      </div>

      {/* Floating Add Button */}
      {view === AppView.HOME && (
        <button 
          onClick={() => { setEditingRecipe(null); setView(AppView.RECIPE_EDIT); }}
          className="fixed bottom-8 right-8 w-16 h-16 bg-pati-orange text-white text-3xl rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-50 ring-4 ring-white"
        >
          +
        </button>
      )}
    </div>
  );
};

interface RecipeFormProps {
  recipe?: Recipe;
  activeProfile: Profile | null;
  onSave: (data: Partial<Recipe>) => void;
  onCancel: () => void;
  isAiLoading: boolean;
  setIsAiLoading: (v: boolean) => void;
}

const RecipeForm: React.FC<RecipeFormProps> = ({ recipe, activeProfile, onSave, onCancel, isAiLoading, setIsAiLoading }) => {
  const [formData, setFormData] = useState<Partial<Recipe>>(recipe || {
    title: '',
    category: 'outros' as any,
    ingredients: '',
    instructions: '',
    externalLink: '',
    imageUrl: '',
    authorName: activeProfile?.name || ''
  });
  const [videoUrl, setVideoUrl] = useState('');
  const [suggestionInput, setSuggestionInput] = useState('');
  const [suggestion, setSuggestion] = useState<any>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsAiLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const result = await gemini.transcribeImage(base64);
        setFormData(prev => ({ ...prev, ...result, imageUrl: reader.result as string }));
      } catch (err) {
        alert('Erro ao transcrever imagem. Verifique sua conexão ou API Key.');
      } finally {
        setIsAiLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleManualImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => {
              setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
          };
          reader.readAsDataURL(file);
      }
  };

  const handleVideoTranscribe = async () => {
    if (!videoUrl) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.transcribeVideoLink(videoUrl);
      setFormData(prev => ({ ...prev, ...result, externalLink: videoUrl }));
    } catch (err) {
      alert('A IA não conseguiu transcrever este vídeo automaticamente, mas salvamos o link para você!');
      setFormData(prev => ({ ...prev, externalLink: videoUrl }));
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleGetSuggestions = async () => {
    if (!suggestionInput) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.getRecipeSuggestions(suggestionInput);
      setSuggestion(result);
    } catch (err) {
      alert('Erro ao buscar sugestões.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleSaveSuggested = () => {
      if (suggestion) {
          setFormData(prev => ({
              ...prev,
              title: suggestion.title,
              ingredients: suggestion.ingredients,
              instructions: suggestion.instructions,
              category: suggestion.category
          }));
          setSuggestion(null);
      }
  };

  return (
    <div className="bg-white rounded-3xl p-8 shadow-lg space-y-8 max-w-3xl mx-auto border border-gray-100">
      <div className="flex justify-between items-center border-b border-gray-50 pb-4">
        <h2 className="text-2xl font-bold text-gray-800">{recipe ? 'Editar Receita' : 'Nova Receita'}</h2>
        <button onClick={onCancel} className="text-gray-400 hover:text-gray-600 p-2">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
        </button>
      </div>

      {isAiLoading && (
        <div className="bg-orange-50 p-6 rounded-2xl border-2 border-dashed border-pati-orange animate-pulse text-center">
          <p className="text-pati-orange font-bold text-lg">👨‍🍳 Chef.AI está trabalhando...</p>
          <p className="text-xs text-orange-400 uppercase tracking-widest mt-1">Sua receita está sendo preparada</p>
        </div>
      )}

      {/* AI Tools Section */}
      {!recipe && (
        <div className="bg-gray-50 p-6 rounded-3xl space-y-6">
          <h3 className="text-xs font-extrabold text-gray-400 uppercase tracking-widest">Ajudantes da Pati (IA)</h3>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <label className="flex flex-col items-center justify-center p-6 bg-white rounded-2xl border-2 border-dashed border-gray-200 cursor-pointer hover:border-pati-orange hover:bg-orange-50 transition-all group shadow-sm">
              <span className="text-4xl mb-2 group-hover:scale-110 transition-transform">📸</span>
              <span className="text-sm font-bold text-gray-700">Digitalizar Foto</span>
              <span className="text-[10px] text-gray-400 uppercase mt-1 text-center leading-tight">Fotos de caderno<br/>ou livros</span>
              <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
            </label>

            <div className="flex flex-col p-6 bg-white rounded-2xl border-2 border-dashed border-gray-200 hover:border-pati-orange hover:bg-orange-50 transition-all space-y-3 shadow-sm">
              <div className="flex flex-col items-center text-center">
                <span className="text-4xl mb-2">🎥</span>
                <span className="text-sm font-bold text-gray-700">Importar Vídeo</span>
              </div>
              <input 
                type="text" 
                placeholder="Cole o link (YouTube/Insta)..."
                className="w-full p-2 text-xs border rounded-lg outline-none focus:ring-1 focus:ring-pati-orange bg-gray-50"
                value={videoUrl}
                onChange={e => setVideoUrl(e.target.value)}
              />
              <button 
                onClick={handleVideoTranscribe}
                className="bg-pati-orange text-white py-2 rounded-lg font-bold text-[10px] uppercase shadow hover:bg-orange-600 disabled:opacity-50 transition-colors"
                disabled={!videoUrl || isAiLoading}
              >
                Transcrever Agora
              </button>
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-gray-200">
             <div className="flex flex-col">
                 <h4 className="text-xs font-bold text-gray-500 uppercase tracking-tight mb-2">O QUE COZINHAR COM O QUE TENHO EM CASA?</h4>
                 <div className="flex gap-2">
                    <input 
                        type="text" 
                        placeholder="Ex: frango, tomate, abacaxi"
                        className="flex-1 p-3 border rounded-xl text-sm outline-none focus:ring-2 focus:ring-pati-orange shadow-inner bg-white"
                        value={suggestionInput}
                        onChange={e => setSuggestionInput(e.target.value)}
                    />
                    <button onClick={handleGetSuggestions} className="bg-pati-orange text-white px-5 py-2 rounded-xl font-bold text-xs uppercase shadow-md hover:bg-orange-600 disabled:opacity-50" disabled={isAiLoading}>Pedir Dica</button>
                 </div>
             </div>

             {suggestion && (
                 <div className="bg-white p-6 rounded-2xl border-2 border-pati-orange shadow-lg space-y-5 animate-in fade-in zoom-in duration-300">
                    <div className="flex justify-between items-start gap-3">
                        <h5 className="font-bold text-gray-800 text-xl leading-tight">{suggestion.title}</h5>
                        <span className="shrink-0 text-[10px] bg-orange-100 text-pati-orange px-3 py-1.5 rounded-full font-extrabold uppercase tracking-wider shadow-sm">
                          {CATEGORIES.find(c => c.id === suggestion.category)?.label || suggestion.category}
                        </span>
                    </div>

                    <div className="space-y-4 max-h-[300px] overflow-y-auto pr-2 scrollbar-hide border-y border-gray-50 py-4">
                      <div>
                          <p className="font-extrabold text-[10px] uppercase text-gray-400 tracking-widest mb-2">INGREDIENTES:</p>
                          <p className="text-sm text-gray-600 whitespace-pre-wrap italic bg-orange-50/30 p-3 rounded-xl">{suggestion.ingredients}</p>
                      </div>
                      <div>
                          <p className="font-extrabold text-[10px] uppercase text-gray-400 tracking-widest mb-2">MODO DE PREPARO:</p>
                          <p className="text-sm text-gray-600 whitespace-pre-wrap leading-relaxed">{suggestion.instructions}</p>
                      </div>
                    </div>

                    <div className="flex gap-3 pt-4">
                        <button onClick={handleGetSuggestions} className="flex-1 py-3 border-2 border-pati-orange text-pati-orange rounded-xl text-xs font-bold hover:bg-orange-50 transition-all flex items-center justify-center gap-2">Refazer 🔄</button>
                        <button onClick={handleSaveSuggested} className="flex-[2] py-3 bg-pati-orange text-white rounded-xl text-xs font-bold shadow-lg hover:bg-orange-600 transition-all flex items-center justify-center gap-2">Salvar no Caderno ✅</button>
                    </div>
                 </div>
             )}
          </div>
        </div>
      )}

      {/* Manual Fields */}
      <div className="space-y-6">
        <div className="flex flex-col items-center">
            <div className="w-full h-64 rounded-3xl bg-gray-50 border-2 border-dashed border-gray-200 overflow-hidden relative group shadow-inner">
                {formData.imageUrl ? (
                    <img src={formData.imageUrl} className="w-full h-full object-cover" />
                ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-gray-300">
                        <span className="text-6xl mb-2">🍳</span>
                        <span className="text-sm font-bold uppercase tracking-widest">Sem Foto da Receita</span>
                    </div>
                )}
                <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                    <span className="text-white font-bold text-sm bg-pati-orange px-6 py-3 rounded-full shadow-lg cursor-pointer transform hover:scale-105 transition-transform">Trocar Foto</span>
                </div>
                <input 
                    type="file" 
                    accept="image/*" 
                    className="absolute inset-0 opacity-0 cursor-pointer" 
                    onChange={handleManualImageUpload}
                />
            </div>
            <p className="text-[10px] text-gray-400 uppercase mt-3 font-extrabold tracking-widest text-center">Toque na imagem para editar a foto da receita</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
                <label className="block text-xs font-extrabold text-gray-400 uppercase tracking-widest mb-2">Título da Receita</label>
                <input 
                    type="text" 
                    className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-pati-orange outline-none shadow-sm transition-colors font-medium"
                    value={formData.title}
                    placeholder="Ex: Torta Holandesa da Pati"
                    onChange={e => setFormData({ ...formData, title: e.target.value })}
                />
            </div>
            <div>
                <label className="block text-xs font-extrabold text-gray-400 uppercase tracking-widest mb-2">Categoria</label>
                <select 
                    className="w-full p-4 border-2 border-gray-100 rounded-xl bg-white focus:border-pati-orange outline-none shadow-sm cursor-pointer font-medium"
                    value={formData.category}
                    onChange={e => setFormData({ ...formData, category: e.target.value as any })}
                >
                    {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.icon} {c.label}</option>)}
                </select>
            </div>
        </div>

        <div>
          <label className="block text-xs font-extrabold text-gray-400 uppercase tracking-widest mb-2">Receita de quem? (Chef/Autor)</label>
          <input 
            type="text" 
            className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-pati-orange outline-none shadow-sm transition-colors font-medium"
            value={formData.authorName}
            onChange={e => setFormData({ ...formData, authorName: e.target.value })}
            placeholder="Nome da pessoa que nos deu a receita"
          />
        </div>

        <div>
          <label className="block text-xs font-extrabold text-gray-400 uppercase tracking-widest mb-2">Ingredientes</label>
          <textarea 
            className="w-full p-4 border-2 border-gray-100 rounded-xl h-40 focus:border-pati-orange outline-none shadow-sm transition-colors resize-none leading-relaxed font-medium bg-orange-50/10"
            value={formData.ingredients}
            placeholder="Liste tudo o que vamos precisar..."
            onChange={e => setFormData({ ...formData, ingredients: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-xs font-extrabold text-gray-400 uppercase tracking-widest mb-2">Modo de Preparo</label>
          <textarea 
            className="w-full p-4 border-2 border-gray-100 rounded-xl h-64 focus:border-pati-orange outline-none shadow-sm transition-colors resize-none leading-relaxed font-medium"
            value={formData.instructions}
            placeholder="Explique o passo a passo com carinho..."
            onChange={e => setFormData({ ...formData, instructions: e.target.value })}
          />
        </div>

        <div>
          <label className="block text-xs font-extrabold text-gray-400 uppercase tracking-widest mb-2">Link de Referência (Opcional)</label>
          <input 
            type="text" 
            className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-pati-orange outline-none shadow-sm transition-colors font-medium bg-gray-50"
            value={formData.externalLink}
            placeholder="https://www.youtube.com/..."
            onChange={e => setFormData({ ...formData, externalLink: e.target.value })}
          />
        </div>

        <div className="flex gap-4 pt-8">
          <button onClick={onCancel} className="flex-1 py-4 border-2 border-gray-100 rounded-2xl font-bold text-gray-400 hover:bg-gray-50 transition-all uppercase text-xs tracking-widest">Descartar</button>
          <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-2xl font-bold shadow-xl hover:bg-orange-600 transform active:scale-95 transition-all uppercase text-xs tracking-widest">Guardar no Caderno</button>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppView, Profile, Recipe } from './types';
import { FAMILY_PASSWORD, LOGO_URL, ICON_URL, CATEGORIES } from './constants';
import { gemini } from './services/geminiService';

const FOOTER_LOGO_URL = "https://i.ibb.co/Xf0T4snH/patitour-2026-01-27-T112542-860.png";

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.LOGIN);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [activeProfile, setActiveProfile] = useState<Profile | null>(null);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [search, setSearch] = useState('');
  const [tempSearch, setTempSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');

  // Login State
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);

  // Profile Create State
  const [newProfileName, setNewProfileName] = useState('');
  const [newProfilePhoto, setNewProfilePhoto] = useState('');
  const [newProfileBirth, setNewProfileBirth] = useState('');

  // Recipe Form State
  const [editingRecipe, setEditingRecipe] = useState<Recipe | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Persistence
  useEffect(() => {
    const savedProfiles = localStorage.getItem('pati_profiles');
    const savedRecipes = localStorage.getItem('pati_recipes');
    if (savedProfiles) setProfiles(JSON.parse(savedProfiles));
    if (savedRecipes) setRecipes(JSON.parse(savedRecipes));
  }, []);

  useEffect(() => {
    localStorage.setItem('pati_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    localStorage.setItem('pati_recipes', JSON.stringify(recipes));
  }, [recipes]);

  const handleLogin = () => {
    if (passwordInput === FAMILY_PASSWORD) {
      setView(AppView.PROFILE_SELECT);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 2000);
    }
  };

  const handleAddProfile = () => {
    if (!newProfileName) return;
    const newProfile: Profile = {
      id: Date.now().toString(),
      name: newProfileName,
      photoUrl: newProfilePhoto || 'https://www.w3schools.com/howto/img_avatar.png',
      birthDate: newProfileBirth,
    };
    setProfiles([...profiles, newProfile]);
    setView(AppView.PROFILE_SELECT);
    setNewProfileName('');
    setNewProfilePhoto('');
    setNewProfileBirth('');
  };

  const handleProfilePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setNewProfilePhoto(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const saveRecipe = (recipeData: Partial<Recipe>) => {
    if (editingRecipe) {
      setRecipes(recipes.map(r => r.id === editingRecipe.id ? { ...r, ...recipeData } as Recipe : r));
    } else {
      const newRecipe: Recipe = {
        id: Date.now().toString(),
        createdAt: Date.now(),
        authorId: activeProfile?.id || 'anonymous',
        authorName: recipeData.authorName || activeProfile?.name || 'Visitante',
        title: recipeData.title || 'Sem título',
        category: (recipeData.category as any) || 'outros',
        ingredients: recipeData.ingredients || '',
        instructions: recipeData.instructions || '',
        externalLink: recipeData.externalLink,
        imageUrl: recipeData.imageUrl,
      };
      setRecipes([newRecipe, ...recipes]);
    }
    setEditingRecipe(null);
    setView(AppView.HOME);
  };

  const deleteRecipe = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir esta receita preciosa?')) {
      setRecipes(recipes.filter(r => r.id !== id));
      setView(AppView.HOME);
    }
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setSearch(tempSearch);
  };

  const Footer = () => (
    <footer className="w-full pt-12 pb-8 flex flex-col items-center justify-center bg-gradient-to-t from-black/40 to-transparent">
      <span className="text-[10px] uppercase tracking-[0.4em] text-gray-400 font-bold mb-3">
        Desenvolvido por
      </span>
      <a 
        href="https://patitour.com.br" 
        target="_blank" 
        rel="noopener noreferrer" 
        className="block"
      >
        <img 
          src={FOOTER_LOGO_URL} 
          alt="Patitour" 
          className="w-28 h-auto grayscale opacity-40 hover:grayscale-0 hover:opacity-100 active:scale-95 transition-all duration-700 cursor-pointer" 
        />
      </a>
    </footer>
  );

  const renderContent = () => {
    if (view === AppView.LOGIN) {
      return (
        <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
          <img src={LOGO_URL} alt="Logo" className="w-48 h-48 rounded-full border-4 border-pati-orange mb-8 shadow-xl object-cover" />
          <h1 className="text-4xl font-cursive mb-12 text-center text-pati-orange">Caderno de receitas da Pati</h1>
          <div className="w-full max-w-sm space-y-4">
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔒</span>
              <input 
                type="password" 
                placeholder="Digite a senha da família" 
                className="w-full py-4 pl-12 pr-4 rounded-2xl text-gray-800 outline-none border-2 border-gray-100 focus:border-pati-orange shadow-lg transition-colors"
                value={passwordInput}
                onChange={(e) => setPasswordInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
              />
            </div>
            <button 
              onClick={handleLogin}
              className="w-full py-4 bg-pati-orange text-white font-bold rounded-2xl shadow-lg hover:bg-orange-600 active:scale-95 transition-all uppercase tracking-wider"
            >
              Entrar na Cozinha
            </button>
            {loginError && <p className="text-center text-sm font-medium text-red-400 animate-pulse">Senha incorreta, tente novamente!</p>}
          </div>
        </div>
      );
    }

    if (view === AppView.PROFILE_SELECT) {
      return (
        <div className="min-h-screen bg-white p-6 flex flex-col items-center">
          <div className="w-20 h-20 rounded-full border-2 border-pati-orange overflow-hidden mb-6 shadow-md">
              <img src={LOGO_URL} alt="Logo" className="w-full h-full object-cover" />
          </div>
          <p className="text-center text-gray-600 italic mb-8 px-4 max-w-md">
            "Nosso caderno de receitas virou app! Agora a gente compartilha segredos de cozinha, 
            fotografa caderninhos antigos e deixa tudo guardado aqui."
          </p>
          <h2 className="text-3xl font-cursive text-gray-800 mb-12">Quem está cozinhando hoje?</h2>

          <div className="grid grid-cols-2 gap-10 w-full max-w-md">
            {profiles.map(p => (
              <button key={p.id} onClick={() => { setActiveProfile(p); setView(AppView.HOME); }} className="flex flex-col items-center group">
                <img src={p.photoUrl} className="w-28 h-28 rounded-full border-2 border-gray-100 group-hover:border-pati-orange shadow-md object-cover mb-3 transition-all transform group-hover:scale-105" />
                <span className="font-semibold text-gray-700">{p.name}</span>
              </button>
            ))}
            <button onClick={() => setView(AppView.PROFILE_CREATE)} className="flex flex-col items-center group">
              <div className="w-28 h-28 rounded-full bg-gray-50 border-2 border-dashed border-gray-200 flex items-center justify-center group-hover:bg-orange-50 group-hover:border-pati-orange transition-all mb-3 shadow-inner">
                <svg className="w-12 h-12 text-gray-300 group-hover:text-pati-orange" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z" />
                </svg>
              </div>
              <span className="font-semibold text-gray-400 group-hover:text-pati-orange transition-colors">Novo Perfil</span>
            </button>
          </div>
        </div>
      );
    }

    if (view === AppView.PROFILE_CREATE) {
      return (
        <div className="min-h-screen bg-gray-50 p-6 flex flex-col">
          <button onClick={() => setView(AppView.PROFILE_SELECT)} className="text-pati-orange mb-6 flex items-center gap-2 font-bold">← Voltar</button>
          <h2 className="text-2xl font-bold text-gray-800 mb-6">Criar Perfil de Família</h2>
          <div className="bg-white p-6 rounded-2xl shadow-md space-y-6">
            <div className="flex flex-col items-center mb-4">
               <div className="w-24 h-24 rounded-full bg-gray-100 border-2 border-dashed border-gray-300 overflow-hidden mb-2 flex items-center justify-center relative">
                  {newProfilePhoto ? (
                      <img src={newProfilePhoto} className="w-full h-full object-cover" />
                  ) : (
                      <span className="text-gray-400 text-xs">Foto</span>
                  )}
                  <input 
                    type="file" 
                    accept="image/*" 
                    className="absolute inset-0 opacity-0 cursor-pointer" 
                    onChange={handleProfilePhotoUpload}
                  />
               </div>
               <p className="text-xs text-pati-orange font-bold uppercase">Toque para carregar foto</p>
            </div>
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Nome Completo</label>
              <input 
                type="text" 
                placeholder="Como quer ser chamado(a)?"
                className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-pati-orange outline-none transition-colors"
                value={newProfileName}
                onChange={e => setNewProfileName(e.target.value)}
              />
            </div>
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Data de Nascimento</label>
              <input 
                type="date" 
                className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-pati-orange outline-none transition-colors"
                value={newProfileBirth}
                onChange={e => setNewProfileBirth(e.target.value)}
              />
            </div>
            <button onClick={handleAddProfile} className="w-full py-4 bg-pati-orange text-white rounded-xl font-bold shadow-lg transform active:scale-95 transition-transform">Criar Perfil</button>
          </div>
        </div>
      );
    }

    const filteredRecipes = recipes.filter(r => {
      const searchLower = search.toLowerCase();
      const matchesSearch = 
        r.title.toLowerCase().includes(searchLower) || 
        r.ingredients.toLowerCase().includes(searchLower) ||
        r.authorName.toLowerCase().includes(searchLower);
      const matchesCategory = categoryFilter === 'all' || r.category === categoryFilter;
      return matchesSearch && matchesCategory;
    });

    return (
      <div className="min-h-screen bg-gray-50">
        {/* Header with Integrated Search */}
        <header className="bg-white p-4 shadow-md sticky top-0 z-40 flex flex-col border-b border-gray-100">
          <div className="flex justify-between items-center mb-3">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full border-2 border-pati-orange overflow-hidden shadow-sm">
                <img src={LOGO_URL} alt="Logo" className="w-full h-full object-cover" />
              </div>
              <h1 className="text-lg font-cursive text-pati-orange leading-tight">Caderno de receitas da Pati</h1>
            </div>
            <div className="flex items-center gap-3">
              <button onClick={() => setView(AppView.AI_TOOLS)} className="p-2 hover:bg-orange-50 rounded-full transition-colors" title="Sugestões da IA">
                <span className="text-2xl">🪄</span>
              </button>
              <img 
                src={activeProfile?.photoUrl} 
                className="w-10 h-10 rounded-full border-2 border-pati-orange cursor-pointer object-cover shadow-sm transform hover:scale-105 transition-transform" 
                onClick={() => setView(AppView.PROFILE_SELECT)}
              />
            </div>
          </div>

          {/* Universal Search Bar with Search Button */}
          {view === AppView.HOME && (
            <form onSubmit={handleSearchSubmit} className="relative w-full max-w-2xl mx-auto flex gap-2">
              <div className="relative flex-1">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔍</span>
                <input 
                  type="text" 
                  placeholder="Buscar por receita, ingrediente ou chef..." 
                  className="w-full p-3 pl-12 rounded-2xl border border-gray-100 shadow-sm focus:ring-2 focus:ring-pati-orange bg-gray-50 text-sm outline-none"
                  value={tempSearch}
                  onChange={e => setTempSearch(e.target.value)}
                />
              </div>
              <button type="submit" className="bg-pati-orange text-white px-6 rounded-2xl font-bold text-xs uppercase shadow-sm hover:bg-orange-600 transition-colors">
                Buscar
              </button>
            </form>
          )}
        </header>

        {/* Content Layout with Vertical Menu */}
        <div className="p-4 max-w-6xl mx-auto flex flex-col md:flex-row gap-6">

          {/* Sidebar Vertical Menu - Visible only on Home */}
          {(view === AppView.HOME) && (
            <aside className="w-full md:w-64 space-y-4">
              <div className="bg-white p-2 rounded-2xl shadow-sm border border-gray-100 sticky top-40">
                  <h3 className="p-3 text-xs font-bold text-gray-400 uppercase tracking-widest border-b border-gray-50 mb-2">Categorias</h3>
                  <nav className="flex flex-col gap-1">
                      <button 
                          onClick={() => setCategoryFilter('all')}
                          className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all ${categoryFilter === 'all' ? 'bg-pati-orange text-white shadow-md' : 'text-gray-600 hover:bg-orange-50'}`}
                      >
                          <span>🍽️</span> Todas as Receitas
                      </button>
                      {CATEGORIES.map(cat => (
                          <button 
                              key={cat.id}
                              onClick={() => setCategoryFilter(cat.id)}
                              className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all ${categoryFilter === cat.id ? 'bg-pati-orange text-white shadow-md' : 'text-gray-600 hover:bg-orange-50'}`}
                          >
                              <span>{cat.icon}</span> {cat.label}
                          </button>
                      ))}
                  </nav>
              </div>
            </aside>
          )}

          {/* Main Area */}
          <main className="flex-1 min-w-0">
              {view === AppView.HOME && (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                  {filteredRecipes.length === 0 ? (
                      <div className="col-span-full text-center py-24 text-gray-400 bg-white rounded-3xl shadow-sm border border-dashed border-gray-200">
                      <p className="text-5xl mb-4">🍳</p>
                      <p className="font-medium">Nenhuma receita encontrada para sua busca.</p>
                      <p className="text-sm mt-1">Limpe o filtro ou crie uma nova receita!</p>
                      </div>
                  ) : (
                      filteredRecipes.map(recipe => (
                      <div key={recipe.id} className="bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl border border-gray-100 group transition-all cursor-pointer flex flex-col" onClick={() => { setEditingRecipe(recipe); setView(AppView.RECIPE_DETAIL); }}>
                          <div className="relative h-48 overflow-hidden">
                              {recipe.imageUrl ? (
                                  <img src={recipe.imageUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110 duration-500" />
                              ) : (
                                  <div className="w-full h-full bg-orange-50 flex items-center justify-center text-4xl">🥘</div>
                              )}
                              <div className="absolute top-3 left-3">
                                  <span className="px-3 py-1 bg-white/90 backdrop-blur-sm text-pati-orange text-[10px] font-bold uppercase rounded-full shadow-sm">
                                      {CATEGORIES.find(c => c.id === recipe.category)?.label}
                                  </span>
                              </div>
                          </div>
                          <div className="p-5 flex-1 flex flex-col">
                              <h3 className="text-xl font-bold text-gray-800 mb-2 group-hover:text-pati-orange transition-colors line-clamp-1">{recipe.title}</h3>
                              <p className="text-sm text-gray-500 mb-4 line-clamp-3 leading-relaxed flex-1">{recipe.ingredients}</p>
                              <div className="flex justify-between items-center border-t border-gray-50 pt-4 mt-auto">
                                  <div className="flex items-center gap-2">
                                      <div className="w-6 h-6 rounded-full bg-pati-orange/10 flex items-center justify-center text-[10px] text-pati-orange font-bold uppercase overflow-hidden">
                                          {profiles.find(p => p.id === recipe.authorId)?.photoUrl ? (
                                            <img src={profiles.find(p => p.id === recipe.authorId)?.photoUrl} className="w-full h-full object-cover" />
                                          ) : recipe.authorName.charAt(0)}
                                      </div>
                                      <span className="text-[10px] text-gray-500 font-bold uppercase tracking-tighter">Chef: {recipe.authorName}</span>
                                  </div>
                                  {recipe.externalLink && <span className="text-[10px] bg-blue-50 text-blue-500 px-2 py-1 rounded font-bold">VÍDEO 🎬</span>}
                              </div>
                          </div>
                      </div>
                      ))
                  )}
              </div>
              )}

              {(view === AppView.RECIPE_DETAIL && editingRecipe) && (
              <div className="bg-white rounded-3xl p-8 shadow-xl max-w-3xl mx-auto border border-gray-100">
                  <div className="flex justify-between items-center mb-8">
                  <button onClick={() => setView(AppView.HOME)} className="text-pati-orange font-bold flex items-center gap-2 hover:translate-x-[-4px] transition-transform">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7"/></svg>
                      Voltar
                  </button>
                  <div className="flex gap-4">
                      <button onClick={() => setView(AppView.RECIPE_EDIT)} className="p-2 hover:bg-gray-50 rounded-full transition-colors text-xl">✏️</button>
                      <button onClick={() => deleteRecipe(editingRecipe.id)} className="p-2 hover:bg-red-50 rounded-full transition-colors text-red-400 text-xl">🗑️</button>
                  </div>
                  </div>

                  {editingRecipe.imageUrl && <img src={editingRecipe.imageUrl} className="w-full h-80 object-cover rounded-3xl mb-8 shadow-md" />}

                  <h2 className="text-4xl font-cursive text-gray-800 mb-4">{editingRecipe.title}</h2>
                  <div className="flex items-center gap-4 mb-8">
                  <span className="px-4 py-1.5 bg-orange-100 text-pati-orange rounded-full text-xs font-extrabold uppercase tracking-widest">
                      {CATEGORIES.find(c => c.id === editingRecipe.category)?.label}
                  </span>
                  <span className="text-sm font-semibold text-gray-400">Receita de <span className="text-gray-700">{editingRecipe.authorName}</span></span>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                  <section className="bg-orange-50/30 p-6 rounded-2xl border border-orange-50">
                      <h4 className="font-extrabold text-pati-orange text-xs uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                          <span className="text-xl">🥛</span> Ingredientes
                      </h4>
                      <p className="text-gray-700 whitespace-pre-wrap leading-loose text-sm font-medium">{editingRecipe.ingredients}</p>
                  </section>

                  <section className="p-6">
                      <h4 className="font-extrabold text-gray-400 text-xs uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                          <span className="text-xl">🔥</span> Modo de Preparo
                      </h4>
                      <p className="text-gray-700 whitespace-pre-wrap leading-relaxed text-sm">{editingRecipe.instructions}</p>
                  </section>
                  </div>

                  {editingRecipe.externalLink && (
                  <section className="mt-8 pt-8 border-t border-gray-100">
                      <h4 className="font-extrabold text-gray-400 text-xs uppercase tracking-widest mb-4">Link Original da Receita</h4>
                      <a href={editingRecipe.externalLink} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 px-6 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-sm hover:bg-blue-100 transition-colors break-all">
                          <span>🎬 Assistir vídeo da receita</span>
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/></svg>
                      </a>
                  </section>
                  )}
              </div>
              )}

              {(view === AppView.RECIPE_EDIT || view === AppView.AI_TOOLS) && (
              <RecipeForm 
                  recipe={editingRecipe || undefined} 
                  activeProfile={activeProfile}
                  onSave={saveRecipe} 
                  onCancel={() => setView(AppView.HOME)} 
                  isAiLoading={isAiLoading}
                  setIsAiLoading={setIsAiLoading}
              />
              )}
          </main>
        </div>

        {/* Floating Add Button */}
        {view === AppView.HOME && (
          <button 
            onClick={() => { setEditingRecipe(null); setView(AppView.RECIPE_EDIT); }}
            className="fixed bottom-8 right-8 w-16 h-16 bg-pati-orange text-white text-3xl rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-50 ring-4 ring-white"
          >
            +
          </button>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex flex-col">
      <div className="flex-grow">
        {renderContent()}
      </div>
      <Footer />
    </div>
  );
};

interface RecipeFormProps {
  recipe?: Recipe;
  activeProfile: Profile | null;
  onSave: (data: Partial<Recipe>) => void;
  onCancel: () => void;
  isAiLoading: boolean;
  setIsAiLoading: (v: boolean) => void;
}

const RecipeForm: React.FC<RecipeFormProps> = ({ recipe, activeProfile, onSave, onCancel, isAiLoading, setIsAiLoading }) => {
  const [formData, setFormData] = useState<Partial<Recipe>>(recipe || {
    title: '',
    category: 'outros' as any,
    ingredients: '',
    instructions: '',
    externalLink: '',
    imageUrl: '',
    authorName: activeProfile?.name || ''
  });
  const [videoUrl, setVideoUrl] = useState('');
  const [suggestionInput, setSuggestionInput] = useState('');
  const [suggestion, setSuggestion] = useState<any>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsAiLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const result = await gemini.transcribeImage(base64);
        setFormData(prev => ({ ...prev, ...result, imageUrl: reader.result as string }));
      } catch (err) {
        alert('Erro ao transcrever imagem. Verifique sua conexão ou API Key.');
      } finally {
        setIsAiLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleManualImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => {
              setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
          };
          reader.readAsDataURL(file);
      }
  };

  const handleVideoTranscribe = async () => {
    if (!videoUrl) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.transcribeVideoLink(videoUrl);
      setFormData(prev => ({ ...prev, ...result, externalLink: videoUrl }));
    } catch (err) {
      alert('A IA não conseguiu transcrever este vídeo automaticamente, mas salvamos o link para você!');
      setFormData(prev => ({ ...prev, externalLink: videoUrl }));
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleGetSuggestions = async () => {
    if (!suggestionInput) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.getRecipeSuggestions(suggestionInput);
      setSuggestion(result);
    } catch (err) {
      alert('Erro ao buscar sugestões.');
    } finally {
