          <button onClick={onDelete} className="text-xl text-red-400">🗑️</button>
        </div>
      </div>

      {recipe.imageUrl && <img src={recipe.imageUrl} className="w-full h-80 object-cover rounded-3xl" />}
      <h2 className="text-4xl font-cursive text-gray-800">{recipe.title}</h2>

      <div className="bg-orange-50 p-6 rounded-2xl">
        <div className="flex justify-between items-center mb-4">
          <h4 className="font-bold text-pati-orange text-sm uppercase tracking-widest">🥘 Ajustar Porções</h4>
          <div className="flex items-center gap-3">
            <button onClick={() => handleAdjust(Math.max(0.5, portionFactor - 0.5))} className="w-8 h-8 rounded-full bg-white text-pati-orange shadow">-</button>
            <span className="font-bold">{portionFactor}x</span>
            <button onClick={() => handleAdjust(portionFactor + 0.5)} className="w-8 h-8 rounded-full bg-white text-pati-orange shadow">+</button>
          </div>
        </div>
        <div className={`text-gray-700 whitespace-pre-wrap leading-loose text-sm ${isAdjusting ? 'opacity-50 animate-pulse' : ''}`}>
          {adjustedIngredients}
        </div>
      </div>

      <div className="space-y-4">
        <h4 className="font-bold text-gray-400 text-sm uppercase tracking-widest">🔥 Modo de Preparo</h4>
        <p className="text-gray-700 whitespace-pre-wrap leading-relaxed text-sm">{recipe.instructions}</p>

        {timerLabels.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {timerLabels.map((l, i) => (
              <button key={i} onClick={() => {
                const num = parseInt(l);
                const isHours = l.toLowerCase().includes('h');
                onStartTimer(isHours ? num * 3600 : num * 60, l);
              }} className="bg-blue-50 text-blue-600 px-4 py-2 rounded-full text-xs font-bold border border-blue-100">⏱️ Iniciar {l}</button>
            ))}
          </div>
        )}
      </div>

      <div className="pt-8 border-t border-gray-100">
        <h4 className="font-bold text-gray-400 text-sm uppercase tracking-widest mb-4">💬 Comentários da Família</h4>
