import { GoogleGenAI, Type } from "@google/genai";

export class GeminiService {
  async transcribeImage(base64Image: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: "image/jpeg" } },
          { text: "Você é um assistente de cozinha especializado. Sua tarefa é extrair com precisão absoluta a receita desta imagem. Se for escrita à mão, use todo o seu conhecimento para decifrar as palavras. Retorne APENAS um objeto JSON estruturado com os campos: title (nome da receita), ingredients (lista detalhada), instructions (passo a passo completo) e category (escolha exclusivamente entre: entradas, saladas, prato_principal, massas, salgados, sobremesas, bebidas, outros)." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async transcribeVideoLink(url: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Analise profundamente o vídeo no link: ${url}. Você deve agir como um transcritor fiel de receitas. Extraia EXATAMENTE a receita que o autor está fazendo. Não invente passos extras, siga o vídeo à risca. Retorne um JSON com: title (nome exato), ingredients (lista de ingredientes com medidas do vídeo), instructions (passo a passo narrado no vídeo) e category (entradas, saladas, prato_principal, massas, salgados, sobremesas, bebidas, outros). Se o vídeo não contiver uma receita clara, tente encontrar referências nos comentários ou descrição via ferramenta de busca.`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async getRecipeSuggestions(ingredients: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Você é um chef premiado. Com base nestes ingredientes disponíveis: ${ingredients}, crie UMA receita completa e detalhada. Seja específico nas quantidades e no modo de preparo. Retorne no formato JSON: title, ingredients, instructions e category (entradas, saladas, prato_principal, massas, salgados, sobremesas, bebidas, outros).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            ingredients: { type: Type.STRING },
            instructions: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "ingredients", "instructions", "category"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  }

  async adjustPortions(ingredients: string, factor: number) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Você é um assistente matemático de cozinha. Multiplique todas as quantidades numéricas destes ingredientes por ${factor}. Retorne APENAS a lista de ingredientes ajustada, mantendo o formato original (texto ou lista), mas com os novos valores calculados. Não adicione nenhum comentário extra. Ingredientes:\n${ingredients}`,
    });
    return response.text;
  }
}

