                          <button onClick={(e) => { e.stopPropagation(); toggleFavorite(recipe.id); }} className="w-10 h-10 rounded-full bg-white/90 shadow-md flex items-center justify-center text-xl transition-transform hover:scale-110">{recipe.isFavorite ? '❤️' : '🤍'}</button>
                          <button onClick={(e) => { e.stopPropagation(); handleWhatsAppShare(recipe.title); }} className="w-10 h-10 rounded-full bg-green-500 shadow-md flex items-center justify-center transition-transform hover:scale-110" title="Compartilhar">
                            <svg className="w-5 h-5 text-white" fill="currentColor" viewBox="0 0 448 512"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-5.5-2.8-23.4-8.6-44.6-27.6-16.5-14.7-27.6-32.8-30.8-38.4-3.2-5.6-.3-8.6 2.5-11.4 2.5-2.5 5.5-6.5 8.3-9.8 2.8-3.2 3.7-5.5 5.5-9.2 1.9-3.7.9-7-.5-9.8-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 13.2 5.8 23.5 9.2 31.5 11.8 13.3 4.2 25.4 3.6 35 2.2 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg>
                          </button>
                        </div>
                      </div>
                      <div className="p-4 flex-1">
                        <h3 className="font-bold text-gray-800 text-lg mb-1">{recipe.title}</h3>
                        <p className="text-xs text-gray-400 font-bold uppercase">De: {recipe.authorName}</p>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {view === AppView.RECIPE_DETAIL && editingRecipe && (
              <RecipeDetailView 
                recipe={editingRecipe} 
                onBack={() => setView(AppView.HOME)} 
                onEdit={() => setView(AppView.RECIPE_EDIT)} 
                onDelete={() => deleteRecipe(editingRecipe.id)} 
                onToggleFavorite={() => toggleFavorite(editingRecipe.id)}
                onAddComment={(t: string) => addComment(editingRecipe.id, t)}
                onStartTimer={(s: number, l: string) => setActiveTimer({ seconds: s, label: l })}
                onWhatsAppShare={() => handleWhatsAppShare(editingRecipe.title)}
              />
            )}

            {(view === AppView.RECIPE_EDIT || view === AppView.AI_TOOLS) && (
              <RecipeForm recipe={editingRecipe || undefined} activeProfile={activeProfile} onSave={saveRecipe} onCancel={() => setView(AppView.HOME)} isAiLoading={isAiLoading} setIsAiLoading={setIsAiLoading} />
            )}
          </main>
        </div>
        {view === AppView.HOME && (
          <button 
            onClick={() => { setEditingRecipe(null); setView(AppView.RECIPE_EDIT); }} 
            className="fixed bottom-8 right-8 w-16 h-16 bg-pati-orange text-white text-3xl rounded-full shadow-2xl flex items-center justify-center z-50 hover:scale-110 active:scale-95 transition-all"
          >
            +
          </button>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex flex-col bg-white">
      <div className="flex-grow">{renderContent()}</div>
      <Footer />
    </div>
  );
};

const RecipeDetailView = ({ recipe, onBack, onEdit, onDelete, onToggleFavorite, onAddComment, onStartTimer, onWhatsAppShare }: any) => {
  const [portionFactor, setPortionFactor] = useState(1);
  const [adjustedIngredients, setAdjustedIngredients] = useState(recipe.ingredients);
  const [isAdjusting, setIsAdjusting] = useState(false);
  const [commentText, setCommentText] = useState('');

  const handleAdjust = async (val: number) => {
    setPortionFactor(val);
    setIsAdjusting(true);
    try {
      const adjusted = await gemini.adjustPortions(recipe.ingredients, val);
      setAdjustedIngredients(adjusted);
    } catch (err) { alert("Erro ao ajustar porções."); } finally { setIsAdjusting(false); }
  };

  const findTimers = (text: string) => {
    const matches = text.match(/\d+\s*(minutos|min|horas|h)/gi);
    return Array.from(new Set(matches)) || [];
  };

  const timerLabels = findTimers(recipe.instructions);

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl max-w-3xl mx-auto border border-gray-100 space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="text-pati-orange font-bold flex items-center gap-2">← Voltar</button>
        <div className="flex gap-4 items-center">
          <button onClick={onWhatsAppShare} className="text-green-500 hover:scale-110 transition-transform"><svg className="w-6 h-6" fill="currentColor" viewBox="0 0 448 512"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-5.5-2.8-23.4-8.6-44.6-27.6-16.5-14.7-27.6-32.8-30.8-38.4-3.2-5.6-.3-8.6 2.5-11.4 2.5-2.5 5.5-6.5 8.3-9.8 2.8-3.2 3.7-5.5 5.5-9.2 1.9-3.7.9-7-.5-9.8-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 13.2 5.8 23.5 9.2 31.5 11.8 13.3 4.2 25.4 3.6 35 2.2 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg></button>
          <button onClick={onToggleFavorite} className="text-2xl transition-transform hover:scale-110">{recipe.isFavorite ? '❤️' : '🤍'}</button>
          <button onClick={onEdit} className="text-xl">✏️</button>
          <button onClick={onDelete} className="text-xl text-red-400">🗑️</button>
        </div>
      </div>

      {recipe.imageUrl && <img src={recipe.imageUrl} className="w-full h-80 object-cover rounded-3xl shadow-md" />}
      <div>
        <h2 className="text-4xl font-cursive text-gray-800 mb-2">{recipe.title}</h2>
        <span className="bg-orange-100 text-pati-orange text-[10px] font-bold uppercase px-3 py-1 rounded-full">{CATEGORIES.find(c => c.id === recipe.category)?.label}</span>
      </div>

      <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100">
        <div className="flex justify-between items-center mb-4">
          <h4 className="font-bold text-pati-orange text-sm uppercase tracking-[0.2em]">🥘 Ajustar Porções</h4>
          <div className="flex items-center gap-3">
            <button onClick={() => handleAdjust(Math.max(0.5, portionFactor - 0.5))} className="w-8 h-8 rounded-full bg-white text-pati-orange shadow flex items-center justify-center font-bold">-</button>
            <span className="font-bold text-sm">{portionFactor}x</span>
            <button onClick={() => handleAdjust(portionFactor + 0.5)} className="w-8 h-8 rounded-full bg-white text-pati-orange shadow flex items-center justify-center font-bold">+</button>
          </div>
        </div>
        <div className={`text-gray-700 whitespace-pre-wrap leading-relaxed text-sm ${isAdjusting ? 'opacity-30' : ''}`}>
          {adjustedIngredients}
        </div>
      </div>

      <div className="space-y-4">
        <h4 className="font-bold text-gray-400 text-sm uppercase tracking-widest">🔥 Modo de Preparo</h4>
        <p className="text-gray-700 whitespace-pre-wrap leading-loose text-sm">{recipe.instructions}</p>

        {timerLabels.length > 0 && (
          <div className="flex flex-wrap gap-2 pt-4">
            {timerLabels.map((l, i) => (
              <button key={i} onClick={() => {
                const num = parseInt(l as string);
                const isHours = (l as string).toLowerCase().includes('h');
                onStartTimer(isHours ? num * 3600 : num * 60, l);
              }} className="bg-blue-50 text-blue-600 px-4 py-2 rounded-full text-xs font-bold border border-blue-100 shadow-sm hover:bg-blue-100 transition-all">⏱️ Iniciar {l}</button>
            ))}
          </div>
        )}
      </div>

      <div className="pt-8 border-t border-gray-100">
        <h4 className="font-bold text-gray-400 text-sm uppercase tracking-widest mb-4">💬 Comentários da Família</h4>
        <div className="space-y-4 mb-6">
          {(recipe.comments || []).length === 0 ? <p className="text-xs text-gray-400 italic">Seja o primeiro a comentar!</p> : (recipe.comments || []).map((c: any) => (
            <div key={c.id} className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
              <p className="text-xs font-bold text-pati-orange mb-1">{c.authorName}</p>
              <p className="text-sm text-gray-700">{c.text}</p>
            </div>
          ))}
        </div>
        <div className="flex gap-2">
          <input type="text" placeholder="Escreva algo..." className="flex-1 p-3 border-2 border-gray-50 rounded-xl text-sm outline-none focus:border-pati-orange transition-all" value={commentText} onChange={e => setCommentText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (onAddComment(commentText), setCommentText(''))} />
          <button onClick={() => { onAddComment(commentText); setCommentText(''); }} className="bg-pati-orange text-white px-6 rounded-xl font-bold text-xs uppercase shadow-sm">Enviar</button>
        </div>
      </div>
    </div>
  );
};

const RecipeForm = ({ recipe, activeProfile, onSave, onCancel, isAiLoading, setIsAiLoading }: any) => {
  const [step, setStep] = useState(recipe ? 'form' : 'options');
  const [formData, setFormData] = useState<Partial<Recipe>>(recipe || {
    title: '', category: 'outros' as any, ingredients: '', instructions: '', authorName: activeProfile?.name || ''
  });
  const [videoUrl, setVideoUrl] = useState('');
  const [suggestionInput, setSuggestionInput] = useState('');

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsAiLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const result = await gemini.transcribeImage(base64);
        setFormData(prev => ({ ...prev, ...result, imageUrl: reader.result as string }));
        setStep('form');
      } catch (err) { 
        alert('Erro na transcrição da IA. Você pode digitar manualmente.'); 
        setStep('form');
      } finally { setIsAiLoading(false); }
    };
    reader.readAsDataURL(file);
  };

  const handleSimpleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleVideoTranscribe = async () => {
    if (!videoUrl) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.transcribeVideoLink(videoUrl);
      setFormData(prev => ({ ...prev, ...result, externalLink: videoUrl }));
      setStep('form');
    } catch (err) { 
      alert('A IA falhou em ler o vídeo, mas o link foi salvo. Complete a receita manualmente.'); 
      setFormData(prev => ({ ...prev, externalLink: videoUrl }));
      setStep('form');
    } finally { setIsAiLoading(false); }
  };

  const handleSuggestion = async () => {
    if (!suggestionInput) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.getRecipeSuggestions(suggestionInput);
      setFormData(prev => ({ ...prev, ...result }));
      setStep('form');
    } catch (err) {
      alert('A IA não conseguiu sugerir no momento.');
    } finally { setIsAiLoading(false); }
  };

  if (step === 'options') {
    return (
      <div className="bg-white rounded-3xl p-8 shadow-lg max-w-lg mx-auto space-y-6 border border-gray-100">
        <div className="flex items-center gap-2 mb-6">
          <span className="text-pati-orange text-3xl font-bold">+</span>
          <h2 className="text-2xl font-bold text-gray-800">Nova Receita</h2>
        </div>

        <div className="space-y-4">
          {/* Foto/Scanner */}
          <label className="block p-8 border-2 border-dashed border-orange-200 rounded-3xl cursor-pointer hover:bg-orange-50 transition-all text-center">
            <div className="text-4xl mb-2">📷</div>
            <span className="text-gray-600 font-medium">Foto/Scanner</span>
            <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
          </label>

          {/* Link Externo */}
          <div className="p-8 border-2 border-dashed border-orange-200 rounded-3xl space-y-4">
            <div className="flex items-center gap-2">
              <span className="text-2xl text-red-500">▶️</span>
              <span className="text-gray-600 font-medium">Link Externo</span>
            </div>
            <input 
              type="text" 
              placeholder="Link do vídeo ou post..." 
              className="w-full p-3 bg-white border border-gray-100 rounded-xl outline-none text-sm shadow-sm"
              value={videoUrl}
              onChange={e => setVideoUrl(e.target.value)}
            />
            <div className="flex gap-2">
              <button 
                onClick={handleVideoTranscribe}
                className="flex-1 py-3 bg-orange-300 text-white rounded-xl font-bold text-sm hover:bg-orange-400"
              >
                Extrair IA
              </button>
              <button 
                onClick={() => { setFormData({...formData, externalLink: videoUrl}); setStep('form'); }}
                className="flex-1 py-3 bg-gray-50 text-gray-400 rounded-xl font-bold text-sm flex items-center justify-center gap-1 hover:bg-gray-100"
              >
                <span>🔗</span> Só Link
              </button>
            </div>
          </div>

          {/* Digitar Receita */}
          <button 
            onClick={() => setStep('form')}
            className="w-full p-8 border-2 border-dashed border-orange-200 rounded-3xl hover:bg-orange-50 transition-all text-center flex flex-col items-center"
          >
            <div className="text-4xl mb-2 text-pati-orange">🖋️</div>
            <span className="text-gray-600 font-medium">Digitar Receita</span>
          </button>

          {/* O que cozinhar */}
          <div className="p-8 border-2 border-dashed border-orange-200 rounded-3xl space-y-4 text-center flex flex-col items-center">
            <div className="text-4xl mb-2">🍜</div>
            <span className="text-gray-600 font-medium">O que cozinhar?</span>
            <div className="w-full flex flex-col gap-2">
               <input 
                 type="text" 
                 placeholder="O que tem na geladeira?" 
                 className="w-full p-2 border rounded-lg text-xs" 
                 value={suggestionInput} 
                 onChange={e => setSuggestionInput(e.target.value)}
               />
               <button onClick={handleSuggestion} className="w-full py-2 bg-pati-orange text-white text-xs rounded-lg font-bold">Sugestão por IA</button>
            </div>
          </div>
        </div>

        <button onClick={onCancel} className="w-full py-4 text-gray-400 font-bold hover:text-gray-600">Cancelar</button>
        {isAiLoading && <div className="fixed inset-0 bg-white/80 flex items-center justify-center z-[100] font-cursive text-2xl text-pati-orange animate-pulse">A IA está preparando tudo...</div>}
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-8 shadow-lg space-y-6 border border-gray-100 max-w-3xl mx-auto animate-in fade-in duration-300">
      <h2 className="text-2xl font-bold text-gray-800">{recipe ? 'Editar' : 'Nova'} Receita</h2>

      {/* Seção de Gerenciamento de Imagem */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Foto do Prato</label>
        <div className="relative group">
          {formData.imageUrl ? (
            <div className="relative h-60 w-full rounded-2xl overflow-hidden shadow-inner border border-gray-100 bg-gray-50">
              <img src={formData.imageUrl} className="w-full h-full object-cover" />
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                <label className="cursor-pointer bg-white text-pati-orange px-4 py-2 rounded-full font-bold text-xs shadow-lg">
                  Alterar Imagem
                  <input type="file" accept="image/*" className="hidden" onChange={handleSimpleImageUpload} />
                </label>
              </div>
            </div>
          ) : (
            <label className="h-60 w-full rounded-2xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center cursor-pointer hover:border-pati-orange transition-all bg-gray-50">
              <span className="text-4xl mb-2">🖼️</span>
              <span className="text-xs font-bold text-gray-400">Adicionar Foto</span>
              <input type="file" accept="image/*" className="hidden" onChange={handleSimpleImageUpload} />
            </label>
          )}
        </div>
      </div>

      {isAiLoading && <div className="p-4 bg-orange-50 text-pati-orange text-center rounded-xl font-bold animate-pulse">Organizando os dados... 👨‍🍳</div>}

      <div className="space-y-4">
        <input type="text" placeholder="Título da Receita" className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange" value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} />
        <select className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange bg-white" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value as any })}>
          {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.icon} {c.label}</option>)}
        </select>
        <input type="text" placeholder="De quem é essa receita?" className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange" value={formData.authorName} onChange={e => setFormData({ ...formData, authorName: e.target.value })} />
        <textarea placeholder="Ingredientes (um por linha)" className="w-full p-4 border rounded-xl h-40 outline-none focus:border-pati-orange resize-none" value={formData.ingredients} onChange={e => setFormData({ ...formData, ingredients: e.target.value })} />
        <textarea placeholder="Modo de Preparo" className="w-full p-4 border rounded-xl h-60 outline-none focus:border-pati-orange resize-none" value={formData.instructions} onChange={e => setFormData({ ...formData, instructions: e.target.value })} />

        {formData.externalLink && (
          <div className="p-3 bg-gray-50 border rounded-xl text-xs text-blue-500 underline break-all">
            Link Original: <a href={formData.externalLink} target="_blank">{formData.externalLink}</a>
          </div>
        )}

        <div className="flex gap-4 pt-4">
          <button onClick={recipe ? onCancel : () => setStep('options')} className="flex-1 py-4 border-2 border-gray-100 rounded-2xl font-bold text-gray-400">Voltar</button>
          <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-2xl font-bold shadow-lg">Guardar no Caderno</button>
        </div>
      </div>
    </div>
  );
};

export default App;

export interface Comment {
  id: string;
  authorName: string;
  text: string;
  createdAt: number;
}

export interface Profile {
  id: string;
  name: string;
  photoUrl: string;
  birthDate: string;
}

export interface Recipe {
  id: string;
  title: string;
  category: 'entradas' | 'saladas' | 'prato_principal' | 'massas' | 'salgados' | 'sobremesas' | 'bebidas' | 'outros';
  ingredients: string;
  instructions: string;
  authorId: string;
  authorName: string;
  externalLink?: string;
  imageUrl?: string;
  createdAt: number;
  isFavorite?: boolean;
  comments?: Comment[];
}

export enum AppView {
  LOGIN,
  PROFILE_SELECT,
  PROFILE_CREATE,
  PROFILE_EDIT,
  HOME,
  RECIPE_DETAIL,
  RECIPE_EDIT,
  AI_TOOLS
}

export const FAMILY_PASSWORD = "2610";

export const CATEGORIES = [
  { id: 'entradas', label: 'Entradas', icon: '🍿' },
  { id: 'saladas', label: 'Saladas', icon: '🥗' },
  { id: 'prato_principal', label: 'Prato Principal', icon: '🍲' },
  { id: 'massas', label: 'Massas', icon: '🍝' },
  { id: 'salgados', label: 'Salgados', icon: '🥟' },
  { id: 'sobremesas', label: 'Sobremesas', icon: '🍰' },
  { id: 'bebidas', label: 'Bebidas', icon: '🍹' },
  { id: 'outros', label: 'Outros', icon: '🍽️' },
];

export const LOGO_URL = "https://i.ibb.co/nMp0TxFf/patitour-2026-02-09-T075024-154.png";
export const ICON_URL = "https://i.ibb.co/LDzRtdMp/patitour-2026-02-09-T075239-692.png";
export const DEFAULT_PROFILE_IMAGE = "https://i.ibb.co/cK9ty308/patitour-33.png";
export const DEFAULT_RECIPE_IMAGE = "https://i.ibb.co/Lhtc9mY5/patitour-32.png";

import React, { useState, useEffect, useRef } from 'react';
import { AppView, Profile, Recipe, Comment } from './types';
import { FAMILY_PASSWORD, LOGO_URL, CATEGORIES, DEFAULT_PROFILE_IMAGE, DEFAULT_RECIPE_IMAGE } from './constants';
import { gemini } from './services/geminiService';

const FOOTER_LOGO_URL = "https://i.ibb.co/Xf0T4snH/patitour-2026-01-27-T112542-860.png";
const WHATSAPP_GROUP_URL = "https://chat.whatsapp.com/HOJsnIu7bk1BIrp6k9MMLI?mode=gi_t";

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.LOGIN);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [activeProfile, setActiveProfile] = useState<Profile | null>(null);
  const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [search, setSearch] = useState('');
  const [tempSearch, setTempSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');

  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [newProfileName, setNewProfileName] = useState('');
  const [newProfilePhoto, setNewProfilePhoto] = useState('');
  const [newProfileBirth, setNewProfileBirth] = useState('');
  const [editingRecipe, setEditingRecipe] = useState<Recipe | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Timer state
  const [activeTimer, setActiveTimer] = useState<{ seconds: number; label: string } | null>(null);
  const timerInterval = useRef<number | null>(null);

  useEffect(() => {
    const savedProfiles = localStorage.getItem('pati_profiles');
    const savedRecipes = localStorage.getItem('pati_recipes');
    if (savedProfiles) setProfiles(JSON.parse(savedProfiles));
    if (savedRecipes) setRecipes(JSON.parse(savedRecipes));
  }, []);

  useEffect(() => {
    localStorage.setItem('pati_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    localStorage.setItem('pati_recipes', JSON.stringify(recipes));
  }, [recipes]);

  useEffect(() => {
    if (activeTimer && activeTimer.seconds > 0) {
      timerInterval.current = window.setInterval(() => {
        setActiveTimer(prev => prev ? { ...prev, seconds: prev.seconds - 1 } : null);
      }, 1000);
    } else if (activeTimer && activeTimer.seconds === 0) {
      if (timerInterval.current) clearInterval(timerInterval.current);
      alert(`⏱️ Tempo esgotado para: ${activeTimer.label}!`);
      setActiveTimer(null);
    }
    return () => { if (timerInterval.current) clearInterval(timerInterval.current); };
  }, [activeTimer]);

  const handleLogin = () => {
    if (passwordInput === FAMILY_PASSWORD) {
      setView(AppView.PROFILE_SELECT);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 2000);
    }
  };

  const handleSaveProfile = () => {
    if (!newProfileName) return;

    if (editingProfile) {
      const updatedProfiles = profiles.map(p => p.id === editingProfile.id ? {
        ...p,
        name: newProfileName,
        photoUrl: newProfilePhoto || DEFAULT_PROFILE_IMAGE,
        birthDate: newProfileBirth
      } : p);
      setProfiles(updatedProfiles);
      setEditingProfile(null);
    } else {
      const newProfile: Profile = {
        id: Date.now().toString(),
        name: newProfileName,
        photoUrl: newProfilePhoto || DEFAULT_PROFILE_IMAGE,
        birthDate: newProfileBirth,
      };
      setProfiles([...profiles, newProfile]);
    }

    setView(AppView.PROFILE_SELECT);
    setNewProfileName('');
    setNewProfilePhoto('');
    setNewProfileBirth('');
  };

  const handleEditProfileClick = (p: Profile) => {
    setEditingProfile(p);
    setNewProfileName(p.name);
    setNewProfilePhoto(p.photoUrl);
    setNewProfileBirth(p.birthDate);
    setView(AppView.PROFILE_EDIT);
  };

  const handleProfilePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setNewProfilePhoto(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleWhatsAppShare = (recipeTitle: string) => {
    const message = encodeURIComponent(`Olha a receita nova que acabei de postar no nosso caderno: ${recipeTitle}! Confere lá no chef.ai 🍳`);
    window.open(`https://api.whatsapp.com/send?text=${message}`, '_blank');
  };

  const saveRecipe = (recipeData: Partial<Recipe>) => {
    if (editingRecipe) {
      setRecipes(recipes.map(r => r.id === editingRecipe.id ? { ...r, ...recipeData } as Recipe : r));
    } else {
      const newRecipe: Recipe = {
        id: Date.now().toString(),
        createdAt: Date.now(),
        authorId: activeProfile?.id || 'anonymous',
        authorName: recipeData.authorName || activeProfile?.name || 'Visitante',
        title: recipeData.title || 'Sem título',
        category: (recipeData.category as any) || 'outros',
        ingredients: recipeData.ingredients || '',
        instructions: recipeData.instructions || '',
        externalLink: recipeData.externalLink,
        imageUrl: recipeData.imageUrl || DEFAULT_RECIPE_IMAGE,
        isFavorite: false,
        comments: [],
      };
      setRecipes([newRecipe, ...recipes]);

      if (window.confirm("Receita guardada! Deseja compartilhar agora no WhatsApp da família?")) {
        handleWhatsAppShare(newRecipe.title);
      }
    }
    setEditingRecipe(null);
    setView(AppView.HOME);
  };

  const toggleFavorite = (recipeId: string) => {
    setRecipes(prev => prev.map(r => r.id === recipeId ? { ...r, isFavorite: !r.isFavorite } : r));
    if (editingRecipe?.id === recipeId) {
      setEditingRecipe(prev => prev ? { ...prev, isFavorite: !prev.isFavorite } : null);
    }
  };

  const addComment = (recipeId: string, text: string) => {
    if (!text.trim() || !activeProfile) return;
    const newComment: Comment = {
      id: Date.now().toString(),
      authorName: activeProfile.name,
      text,
      createdAt: Date.now(),
    };
    setRecipes(prev => prev.map(r => r.id === recipeId ? { ...r, comments: [...(r.comments || []), newComment] } : r));
    if (editingRecipe?.id === recipeId) {
      setEditingRecipe(prev => prev ? { ...prev, comments: [...(prev.comments || []), newComment] } : null);
    }
  };

  const deleteRecipe = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir esta receita preciosa?')) {
      setRecipes(recipes.filter(r => r.id !== id));
      setView(AppView.HOME);
    }
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setSearch(tempSearch);
  };

  const Footer = () => (
    <footer className="w-full pt-16 pb-12 flex flex-col items-center justify-center bg-white border-t border-gray-100">
      <span className="text-[10px] uppercase tracking-[0.4em] text-gray-400 font-bold mb-4">Desenvolvido por</span>
      <a href="https://easybyzcreatorpersonalapps.vercel.app/" target="_blank" rel="noopener noreferrer" className="block">
        <img src={FOOTER_LOGO_URL} alt="Easy Byz" className="w-28 h-auto grayscale opacity-40 hover:grayscale-0 hover:opacity-100 active:scale-95 transition-all duration-700 cursor-pointer" />
      </a>
    </footer>
  );

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const renderContent = () => {
    if (view === AppView.LOGIN) {
      return (
        <div className="min-h-[80vh] bg-white flex flex-col items-center justify-center p-6">
          <img src={LOGO_URL} alt="Logo" className="w-48 h-48 rounded-full border-4 border-pati-orange mb-8 shadow-xl object-cover" />
          <h1 className="text-4xl font-cursive mb-12 text-center text-pati-orange">Caderno de receitas da Pati</h1>
          <div className="w-full max-w-sm space-y-4">
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔒</span>
              <input 
                type="password" 
                placeholder="Digite a senha da família" 
                className="w-full py-4 pl-12 pr-4 rounded-2xl text-gray-800 outline-none border-2 border-gray-100 focus:border-pati-orange shadow-lg transition-colors"
                value={passwordInput}
                onChange={(e) => setPasswordInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
              />
            </div>
            <button onClick={handleLogin} className="w-full py-4 bg-pati-orange text-white font-bold rounded-2xl shadow-lg hover:bg-orange-600 active:scale-95 transition-all uppercase tracking-wider">Entrar na Cozinha</button>
            {loginError && <p className="text-center text-sm font-medium text-red-400 animate-pulse">Senha incorreta!</p>}
          </div>
        </div>
      );
    }

    if (view === AppView.PROFILE_SELECT) {
      return (
        <div className="min-h-screen bg-white p-6 flex flex-col items-center text-center">
          <img src={LOGO_URL} alt="Logo" className="w-32 h-32 rounded-full border-4 border-pati-orange mb-8 shadow-xl object-cover" />

          <p className="text-gray-600 italic font-medium leading-relaxed max-w-md mb-12 px-4">
            "Nosso caderno de receitas virou app! Agora a gente compartilha segredos de cozinha, fotografa caderninhos antigos e deixa tudo guardado aqui — com direito a 'assinatura' de quem mandou a receita. Vamos cozinhar juntas, mesmo de longe?"
          </p>

          <h2 className="text-3xl font-cursive text-gray-800 mb-12">Quem está cozinhando hoje?</h2>

          <div className="grid grid-cols-2 gap-10 w-full max-w-md">
            {profiles.map(p => (
              <div key={p.id} className="relative group">
                <button onClick={() => { setActiveProfile(p); setView(AppView.HOME); }} className="flex flex-col items-center w-full">
                  <img src={p.photoUrl || DEFAULT_PROFILE_IMAGE} className="w-28 h-28 rounded-full border-2 border-gray-100 group-hover:border-pati-orange shadow-md object-cover mb-3 transition-all transform group-hover:scale-105" />
                  <span className="font-semibold text-gray-700">{p.name}</span>
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); handleEditProfileClick(p); }}
                  className="absolute top-0 right-0 bg-white shadow-md border border-gray-100 p-2 rounded-full text-xs hover:text-pati-orange transition-colors"
                >
                  ✏️
                </button>
              </div>
            ))}
            <button onClick={() => { 
                setEditingProfile(null); 
                setNewProfileName(''); 
                setNewProfilePhoto(''); 
                setNewProfileBirth(''); 
                setView(AppView.PROFILE_CREATE); 
              }} className="flex flex-col items-center group">
              <div className="w-28 h-28 rounded-full bg-white border-2 border-dashed border-gray-200 flex items-center justify-center group-hover:border-pati-orange transition-all mb-3 shadow-sm">
                <svg className="w-12 h-12 text-gray-200 group-hover:text-pati-orange transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z" />
                </svg>
              </div>
              <span className="font-bold text-gray-300 group-hover:text-pati-orange transition-colors">Novo Perfil</span>
            </button>
          </div>
        </div>
      );
    }

    if (view === AppView.PROFILE_CREATE || view === AppView.PROFILE_EDIT) {
      return (
        <div className="min-h-screen bg-white p-6 flex flex-col">
          <button onClick={() => setView(AppView.PROFILE_SELECT)} className="text-pati-orange mb-6 flex items-center gap-2 font-bold">← Voltar</button>
          <div className="bg-white p-6 rounded-2xl shadow-md space-y-6 border border-gray-100 max-w-md mx-auto w-full">
            <h2 className="text-2xl font-bold text-center text-gray-800">{editingProfile ? 'Editar Perfil' : 'Criar Perfil'}</h2>
            <div className="flex flex-col items-center mb-4">
               <div className="w-24 h-24 rounded-full bg-gray-100 border-2 border-dashed border-gray-300 overflow-hidden mb-2 flex items-center justify-center relative">
                  <img src={newProfilePhoto || DEFAULT_PROFILE_IMAGE} className="w-full h-full object-cover" />
                  <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleProfilePhotoUpload} />
               </div>
               <p className="text-xs text-pati-orange font-bold uppercase">Toque para carregar foto</p>
            </div>
            <input type="text" placeholder="Nome Completo" className="w-full p-4 border-2 border-gray-100 rounded-xl outline-none focus:border-pati-orange" value={newProfileName} onChange={e => setNewProfileName(e.target.value)} />
            <input type="date" className="w-full p-4 border-2 border-gray-100 rounded-xl outline-none focus:border-pati-orange" value={newProfileBirth} onChange={e => setNewProfileBirth(e.target.value)} />
            <button onClick={handleSaveProfile} className="w-full py-4 bg-pati-orange text-white rounded-xl font-bold">{editingProfile ? 'Salvar Alterações' : 'Criar Perfil'}</button>
          </div>
        </div>
      );
    }

    const filteredRecipes = recipes.filter(r => {
      const searchLower = search.toLowerCase();
      const matchesSearch = r.title.toLowerCase().includes(searchLower) || r.ingredients.toLowerCase().includes(searchLower) || r.authorName.toLowerCase().includes(searchLower);
      const matchesCategory = categoryFilter === 'all' || r.category === categoryFilter;
      const matchesFavorites = categoryFilter === 'favoritos' ? r.isFavorite : true;
      return matchesSearch && (categoryFilter === 'favoritos' ? r.isFavorite : matchesCategory);
    });

    return (
      <div className="min-h-screen bg-white">
        {activeTimer && (
          <div className="fixed top-0 left-0 w-full bg-pati-orange text-white p-3 z-[60] flex justify-between items-center shadow-lg animate-bounce">
            <span className="font-bold flex items-center gap-2">⏱️ Timer: {activeTimer.label} - {formatTime(activeTimer.seconds)}</span>
            <button onClick={() => setActiveTimer(null)} className="bg-white/20 p-1 px-3 rounded-lg text-xs font-bold">PARAR</button>
          </div>
        )}

        <header className="bg-white p-4 shadow-md sticky top-0 z-40 flex flex-col border-b border-gray-100">
          <div className="flex justify-between items-center mb-3">
            <div className="flex items-center gap-3">
              <img src={LOGO_URL} alt="Logo" className="w-10 h-10 rounded-full border-2 border-pati-orange" />
              <h1 className="text-lg font-cursive text-pati-orange leading-tight">Caderno da Pati</h1>
            </div>
            <div className="flex items-center gap-3">
              <button onClick={() => setView(AppView.AI_TOOLS)} className="p-2 text-2xl">🪄</button>
              <img src={activeProfile?.photoUrl || DEFAULT_PROFILE_IMAGE} className="w-10 h-10 rounded-full border-2 border-pati-orange cursor-pointer object-cover shadow-sm" onClick={() => setView(AppView.PROFILE_SELECT)} />
            </div>
          </div>
          {view === AppView.HOME && (
            <form onSubmit={handleSearchSubmit} className="flex gap-2">
              <input type="text" placeholder="Buscar..." className="flex-1 p-2 px-4 rounded-xl border border-gray-100 shadow-sm focus:ring-1 focus:ring-pati-orange outline-none bg-gray-50 text-sm" value={tempSearch} onChange={e => setTempSearch(e.target.value)} />
              <button type="submit" className="bg-pati-orange text-white px-4 rounded-xl font-bold text-xs uppercase shadow-sm">Buscar</button>
            </form>
          )}
        </header>

        <div className="p-4 max-w-6xl mx-auto flex flex-col md:flex-row gap-6">
          {view === AppView.HOME && (
            <aside className="w-full md:w-64 space-y-2">
              <div className="bg-white p-2 rounded-2xl shadow-sm border border-gray-100">
                <button onClick={() => setCategoryFilter('favoritos')} className={`w-full text-left px-4 py-3 rounded-xl font-bold flex items-center gap-2 mb-2 transition-all ${categoryFilter === 'favoritos' ? 'bg-red-50 text-red-500 shadow-sm' : 'text-gray-600 hover:bg-red-50'}`}>❤️ Favoritas da Pati</button>
                <button onClick={() => setCategoryFilter('all')} className={`w-full text-left px-4 py-3 rounded-xl font-bold mb-1 transition-all ${categoryFilter === 'all' ? 'bg-pati-orange text-white shadow-md' : 'text-gray-600 hover:bg-orange-50'}`}>🍽️ Todas</button>
                {CATEGORIES.map(cat => (
                  <button key={cat.id} onClick={() => setCategoryFilter(cat.id)} className={`w-full text-left px-4 py-3 rounded-xl font-bold flex items-center gap-2 transition-all ${categoryFilter === cat.id ? 'bg-pati-orange text-white shadow-md' : 'text-gray-600 hover:bg-orange-50'}`}>{cat.icon} {cat.label}</button>
                ))}
              </div>
              <a href={WHATSAPP_GROUP_URL} target="_blank" rel="noopener noreferrer" className="w-full text-left px-4 py-4 rounded-xl font-bold text-green-600 bg-green-50 flex items-center justify-center gap-2 mt-4 shadow-sm hover:bg-green-100 transition-colors">
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 448 512"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-5.5-2.8-23.4-8.6-44.6-27.6-16.5-14.7-27.6-32.8-30.8-38.4-3.2-5.6-.3-8.6 2.5-11.4 2.5-2.5 5.5-6.5 8.3-9.8 2.8-3.2 3.7-5.5 5.5-9.2 1.9-3.7.9-7-.5-9.8-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 13.2 5.8 23.5 9.2 31.5 11.8 13.3 4.2 25.4 3.6 35 2.2 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg>
                Grupo da Família
              </a>
            </aside>
          )}

          <main className="flex-1 min-w-0">
            {view === AppView.HOME && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                {filteredRecipes.length === 0 ? (
                    <div className="col-span-full text-center py-24 text-gray-400">Poxa, nenhuma receita aqui! Cozinhe algo novo!</div>
                ) : (
                  filteredRecipes.map(recipe => (
                    <div key={recipe.id} className="bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl border border-gray-100 cursor-pointer transition-all flex flex-col group" onClick={() => { setEditingRecipe(recipe); setView(AppView.RECIPE_DETAIL); }}>
                      <div className="relative h-44 overflow-hidden">
                        <img src={recipe.imageUrl || DEFAULT_RECIPE_IMAGE} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                        <div className="absolute top-2 right-2 flex flex-col gap-2">
                          <button onClick={(e) => { e.stopPropagation(); toggleFavorite(recipe.id); }} className="w-10 h-10 rounded-full bg-white/90 shadow-md flex items-center justify-center text-xl transition-transform hover:scale-110">{recipe.isFavorite ? '❤️' : '🤍'}</button>
                          <button onClick={(e) => { e.stopPropagation(); handleWhatsAppShare(recipe.title); }} className="w-10 h-10 rounded-full bg-green-500 shadow-md flex items-center justify-center transition-transform hover:scale-110" title="Compartilhar">
                            <svg className="w-5 h-5 text-white" fill="currentColor" viewBox="0 0 448 512"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-5.5-2.8-23.4-8.6-44.6-27.6-16.5-14.7-27.6-32.8-30.8-38.4-3.2-5.6-.3-8.6 2.5-11.4 2.5-2.5 5.5-6.5 8.3-9.8 2.8-3.2 3.7-5.5 5.5-9.2 1.9-3.7.9-7-.5-9.8-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 13.2 5.8 23.5 9.2 31.5 11.8 13.3 4.2 25.4 3.6 35 2.2 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg>
                          </button>
                        </div>
                      </div>
                      <div className="p-4 flex-1">
                        <h3 className="font-bold text-gray-800 text-lg mb-1">{recipe.title}</h3>
                        <p className="text-xs text-gray-400 font-bold uppercase">De: {recipe.authorName}</p>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {view === AppView.RECIPE_DETAIL && editingRecipe && (
              <RecipeDetailView 
                recipe={editingRecipe} 
                onBack={() => setView(AppView.HOME)} 
                onEdit={() => setView(AppView.RECIPE_EDIT)} 
                onDelete={() => deleteRecipe(editingRecipe.id)} 
                onToggleFavorite={() => toggleFavorite(editingRecipe.id)}
                onAddComment={(t: string) => addComment(editingRecipe.id, t)}
                onStartTimer={(s: number, l: string) => setActiveTimer({ seconds: s, label: l })}
                onWhatsAppShare={() => handleWhatsAppShare(editingRecipe.title)}
              />
            )}

            {(view === AppView.RECIPE_EDIT || view === AppView.AI_TOOLS) && (
              <RecipeForm recipe={editingRecipe || undefined} activeProfile={activeProfile} onSave={saveRecipe} onCancel={() => setView(AppView.HOME)} isAiLoading={isAiLoading} setIsAiLoading={setIsAiLoading} />
            )}
          </main>
        </div>
        {view === AppView.HOME && (
          <button 
            onClick={() => { setEditingRecipe(null); setView(AppView.RECIPE_EDIT); }} 
            className="fixed bottom-8 right-8 w-16 h-16 bg-pati-orange text-white text-3xl rounded-full shadow-2xl flex items-center justify-center z-50 hover:scale-110 active:scale-95 transition-all"
          >
            +
          </button>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex flex-col bg-white">
      <div className="flex-grow">{renderContent()}</div>
      <Footer />
    </div>
  );
};

const RecipeDetailView = ({ recipe, onBack, onEdit, onDelete, onToggleFavorite, onAddComment, onStartTimer, onWhatsAppShare }: any) => {
  const [portionFactor, setPortionFactor] = useState(1);
  const [adjustedIngredients, setAdjustedIngredients] = useState(recipe.ingredients);
  const [isAdjusting, setIsAdjusting] = useState(false);
  const [commentText, setCommentText] = useState('');

  const handleAdjust = async (val: number) => {
    setPortionFactor(val);
    setIsAdjusting(true);
    try {
      const adjusted = await gemini.adjustPortions(recipe.ingredients, val);
      setAdjustedIngredients(adjusted);
    } catch (err) { alert("Erro ao ajustar porções."); } finally { setIsAdjusting(false); }
  };

  const findTimers = (text: string) => {
    const matches = text.match(/\d+\s*(minutos|min|horas|h)/gi);
    return Array.from(new Set(matches)) || [];
  };

  const timerLabels = findTimers(recipe.instructions);

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl max-w-3xl mx-auto border border-gray-100 space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="text-pati-orange font-bold flex items-center gap-2">← Voltar</button>
        <div className="flex gap-4 items-center">
          <button onClick={onWhatsAppShare} className="text-green-500 hover:scale-110 transition-transform"><svg className="w-6 h-6" fill="currentColor" viewBox="0 0 448 512"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-5.5-2.8-23.4-8.6-44.6-27.6-16.5-14.7-27.6-32.8-30.8-38.4-3.2-5.6-.3-8.6 2.5-11.4 2.5-2.5 5.5-6.5 8.3-9.8 2.8-3.2 3.7-5.5 5.5-9.2 1.9-3.7.9-7-.5-9.8-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 13.2 5.8 23.5 9.2 31.5 11.8 13.3 4.2 25.4 3.6 35 2.2 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg></button>
          <button onClick={onToggleFavorite} className="text-2xl transition-transform hover:scale-110">{recipe.isFavorite ? '❤️' : '🤍'}</button>
          <button onClick={onEdit} className="text-xl">✏️</button>
          <button onClick={onDelete} className="text-xl text-red-400">🗑️</button>
        </div>
      </div>

      <img src={recipe.imageUrl || DEFAULT_RECIPE_IMAGE} className="w-full h-80 object-cover rounded-3xl shadow-md" />
      <div>
        <h2 className="text-4xl font-cursive text-gray-800 mb-2">{recipe.title}</h2>
        <span className="bg-orange-100 text-pati-orange text-[10px] font-bold uppercase px-3 py-1 rounded-full">{CATEGORIES.find(c => c.id === recipe.category)?.label}</span>
      </div>

      <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100">
        <div className="flex justify-between items-center mb-4">
          <h4 className="font-bold text-pati-orange text-sm uppercase tracking-[0.2em]">🥘 Ajustar Porções</h4>
          <div className="flex items-center gap-3">
            <button onClick={() => handleAdjust(Math.max(0.5, portionFactor - 0.5))} className="w-8 h-8 rounded-full bg-white text-pati-orange shadow flex items-center justify-center font-bold">-</button>
            <span className="font-bold text-sm">{portionFactor}x</span>
            <button onClick={() => handleAdjust(portionFactor + 0.5)} className="w-8 h-8 rounded-full bg-white text-pati-orange shadow flex items-center justify-center font-bold">+</button>
          </div>
        </div>
        <div className={`text-gray-700 whitespace-pre-wrap leading-relaxed text-sm ${isAdjusting ? 'opacity-30' : ''}`}>
          {adjustedIngredients}
        </div>
      </div>

      <div className="space-y-4">
        <h4 className="font-bold text-gray-400 text-sm uppercase tracking-widest">🔥 Modo de Preparo</h4>
        <p className="text-gray-700 whitespace-pre-wrap leading-loose text-sm">{recipe.instructions}</p>

        {timerLabels.length > 0 && (
          <div className="flex flex-wrap gap-2 pt-4">
            {timerLabels.map((l, i) => (
              <button key={i} onClick={() => {
                const num = parseInt(l as string);
                const isHours = (l as string).toLowerCase().includes('h');
                onStartTimer(isHours ? num * 3600 : num * 60, l);
              }} className="bg-blue-50 text-blue-600 px-4 py-2 rounded-full text-xs font-bold border border-blue-100 shadow-sm hover:bg-blue-100 transition-all">⏱️ Iniciar {l}</button>
            ))}
          </div>
        )}
      </div>

      <div className="pt-8 border-t border-gray-100">
        <h4 className="font-bold text-gray-400 text-sm uppercase tracking-widest mb-4">💬 Comentários da Família</h4>
        <div className="space-y-4 mb-6">
          {(recipe.comments || []).length === 0 ? <p className="text-xs text-gray-400 italic">Seja o primeiro a comentar!</p> : (recipe.comments || []).map((c: any) => (
            <div key={c.id} className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
              <p className="text-xs font-bold text-pati-orange mb-1">{c.authorName}</p>
              <p className="text-sm text-gray-700">{c.text}</p>
            </div>
          ))}
        </div>
        <div className="flex gap-2">
          <input type="text" placeholder="Escreva algo..." className="flex-1 p-3 border-2 border-gray-50 rounded-xl text-sm outline-none focus:border-pati-orange transition-all" value={commentText} onChange={e => setCommentText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (onAddComment(commentText), setCommentText(''))} />
          <button onClick={() => { onAddComment(commentText); setCommentText(''); }} className="bg-pati-orange text-white px-6 rounded-xl font-bold text-xs uppercase shadow-sm">Enviar</button>
        </div>
      </div>
    </div>
  );
};

const RecipeForm = ({ recipe, activeProfile, onSave, onCancel, isAiLoading, setIsAiLoading }: any) => {
  const [step, setStep] = useState(recipe ? 'form' : 'options');
  const [formData, setFormData] = useState<Partial<Recipe>>(recipe || {
    title: '', category: 'outros' as any, ingredients: '', instructions: '', authorName: activeProfile?.name || ''
  });
  const [videoUrl, setVideoUrl] = useState('');
  const [suggestionInput, setSuggestionInput] = useState('');

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsAiLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const result = await gemini.transcribeImage(base64);
        setFormData(prev => ({ ...prev, ...result, imageUrl: reader.result as string }));
        setStep('form');
      } catch (err) { 
        alert('Erro na transcrição da IA. Você pode digitar manualmente.'); 
        setStep('form');
      } finally { setIsAiLoading(false); }
    };
    reader.readAsDataURL(file);
  };

  const handleSimpleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleVideoTranscribe = async () => {
    if (!videoUrl) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.transcribeVideoLink(videoUrl);
      setFormData(prev => ({ ...prev, ...result, externalLink: videoUrl }));
      setStep('form');
    } catch (err) { 
      alert('A IA falhou em ler o vídeo, mas o link foi salvo. Complete a receita manualmente.'); 
      setFormData(prev => ({ ...prev, externalLink: videoUrl }));
      setStep('form');
    } finally { setIsAiLoading(false); }
  };

  const handleSuggestion = async () => {
    if (!suggestionInput) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.getRecipeSuggestions(suggestionInput);
      setFormData(prev => ({ ...prev, ...result }));
      setStep('form');
    } catch (err) {
      alert('A IA não conseguiu sugerir no momento.');
    } finally { setIsAiLoading(false); }
  };

  if (step === 'options') {
    return (
      <div className="bg-white rounded-3xl p-8 shadow-lg max-w-lg mx-auto space-y-6 border border-gray-100">
        <div className="flex items-center gap-2 mb-6">
          <span className="text-pati-orange text-3xl font-bold">+</span>
          <h2 className="text-2xl font-bold text-gray-800">Nova Receita</h2>
        </div>

        <div className="space-y-4">
          {/* Foto/Scanner */}
          <label className="block p-8 border-2 border-dashed border-orange-200 rounded-3xl cursor-pointer hover:bg-orange-50 transition-all text-center">
            <div className="text-4xl mb-2">📷</div>
            <span className="text-gray-600 font-medium">Foto/Scanner</span>
            <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
          </label>

          {/* Link Externo */}
          <div className="p-8 border-2 border-dashed border-orange-200 rounded-3xl space-y-4">
            <div className="flex items-center gap-2">
              <span className="text-2xl text-red-500">▶️</span>
              <span className="text-gray-600 font-medium">Link Externo</span>
            </div>
            <input 
              type="text" 
              placeholder="Link do vídeo ou post..." 
              className="w-full p-3 bg-white border border-gray-100 rounded-xl outline-none text-sm shadow-sm"
              value={videoUrl}
              onChange={e => setVideoUrl(e.target.value)}
            />
            <div className="flex gap-2">
              <button 
                onClick={handleVideoTranscribe}
                className="flex-1 py-3 bg-orange-300 text-white rounded-xl font-bold text-sm hover:bg-orange-400"
              >
                Extrair IA
              </button>
              <button 
                onClick={() => { setFormData({...formData, externalLink: videoUrl}); setStep('form'); }}
                className="flex-1 py-3 bg-gray-50 text-gray-400 rounded-xl font-bold text-sm flex items-center justify-center gap-1 hover:bg-gray-100"
              >
                <span>🔗</span> Só Link
              </button>
            </div>
          </div>

          {/* Digitar Receita */}
          <button 
            onClick={() => setStep('form')}
            className="w-full p-8 border-2 border-dashed border-orange-200 rounded-3xl hover:bg-orange-50 transition-all text-center flex flex-col items-center"
          >
            <div className="text-4xl mb-2 text-pati-orange">🖋️</div>
            <span className="text-gray-600 font-medium">Digitar Receita</span>
          </button>

          {/* O que cozinhar */}
          <div className="p-8 border-2 border-dashed border-orange-200 rounded-3xl space-y-4 text-center flex flex-col items-center">
            <div className="text-4xl mb-2">🍜</div>
            <span className="text-gray-600 font-medium">O que cozinhar?</span>
            <div className="w-full flex flex-col gap-2">
               <input 
                 type="text" 
                 placeholder="O que tem na geladeira?" 
                 className="w-full p-2 border rounded-lg text-xs" 
                 value={suggestionInput} 
                 onChange={e => setSuggestionInput(e.target.value)}
               />
               <button onClick={handleSuggestion} className="w-full py-2 bg-pati-orange text-white text-xs rounded-lg font-bold">Sugestão por IA</button>
            </div>
          </div>
        </div>

        <button onClick={onCancel} className="w-full py-4 text-gray-400 font-bold hover:text-gray-600">Cancelar</button>
        {isAiLoading && <div className="fixed inset-0 bg-white/80 flex items-center justify-center z-[100] font-cursive text-2xl text-pati-orange animate-pulse">A IA está preparando tudo...</div>}
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-8 shadow-lg space-y-6 border border-gray-100 max-w-3xl mx-auto animate-in fade-in duration-300">
      <h2 className="text-2xl font-bold text-gray-800">{recipe ? 'Editar' : 'Nova'} Receita</h2>

      {/* Seção de Gerenciamento de Imagem */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Foto do Prato</label>
        <div className="relative group">
          <div className="relative h-60 w-full rounded-2xl overflow-hidden shadow-inner border border-gray-100 bg-gray-50">
            <img src={formData.imageUrl || DEFAULT_RECIPE_IMAGE} className="w-full h-full object-cover" />
            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
              <label className="cursor-pointer bg-white text-pati-orange px-4 py-2 rounded-full font-bold text-xs shadow-lg">
                Alterar Imagem
                <input type="file" accept="image/*" className="hidden" onChange={handleSimpleImageUpload} />
              </label>
            </div>
          </div>
        </div>
      </div>

      {isAiLoading && <div className="p-4 bg-orange-50 text-pati-orange text-center rounded-xl font-bold animate-pulse">Organizando os dados... 👨‍🍳</div>}

      <div className="space-y-4">
        <input type="text" placeholder="Título da Receita" className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange" value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} />
        <select className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange bg-white" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value as any })}>
          {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.icon} {c.label}</option>)}
        </select>
        <input type="text" placeholder="De quem é essa receita?" className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange" value={formData.authorName} onChange={e => setFormData({ ...formData, authorName: e.target.value })} />
        <textarea placeholder="Ingredientes (um por linha)" className="w-full p-4 border rounded-xl h-40 outline-none focus:border-pati-orange resize-none" value={formData.ingredients} onChange={e => setFormData({ ...formData, ingredients: e.target.value })} />
        <textarea placeholder="Modo de Preparo" className="w-full p-4 border rounded-xl h-60 outline-none focus:border-pati-orange resize-none" value={formData.instructions} onChange={e => setFormData({ ...formData, instructions: e.target.value })} />

        {formData.externalLink && (
          <div className="p-3 bg-gray-50 border rounded-xl text-xs text-blue-500 underline break-all">
            Link Original: <a href={formData.externalLink} target="_blank">{formData.externalLink}</a>
          </div>
        )}

        <div className="flex gap-4 pt-4">
          <button onClick={recipe ? onCancel : () => setStep('options')} className="flex-1 py-4 border-2 border-gray-100 rounded-2xl font-bold text-gray-400">Voltar</button>
          <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-2xl font-bold shadow-lg">Guardar no Caderno</button>
        </div>
      </div>
    </div>
  );
};

export default App;

