  const [isAiLoading, setIsAiLoading] = useState(false);

  // Timer state
  const [activeTimer, setActiveTimer] = useState<{ seconds: number; label: string } | null>(null);
  const timerInterval = useRef<number | null>(null);

  // Sincronização com Firebase
  useEffect(() => {
    const qProfiles = query(collection(db, "profiles"), orderBy("name"));
    const unsubProfiles = onSnapshot(qProfiles, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Profile));
      setProfiles(data);
    });

    const qRecipes = query(collection(db, "recipes"), orderBy("createdAt", "desc"));
    const unsubRecipes = onSnapshot(qRecipes, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Recipe));
      setRecipes(data);
    });

    return () => {
      unsubProfiles();
      unsubRecipes();
    };
  }, []);

  useEffect(() => {
    if (activeTimer && activeTimer.seconds > 0) {
      timerInterval.current = window.setInterval(() => {
        setActiveTimer(prev => prev ? { ...prev, seconds: prev.seconds - 1 } : null);
      }, 1000);
    } else if (activeTimer && activeTimer.seconds === 0) {
      if (timerInterval.current) clearInterval(timerInterval.current);
      alert(`⏱️ Tempo esgotado para: ${activeTimer.label}!`);
      setActiveTimer(null);
    }
    return () => { if (timerInterval.current) clearInterval(timerInterval.current); };
  }, [activeTimer]);

  const handleLogin = () => {
