// Função utilitária para compressão de imagem
const compressImage = (base64: string, maxWidth = 800): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      if (width > maxWidth) {
        height *= maxWidth / width;
        width = maxWidth;
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(img, 0, 0, width, height);
      // Retorna em JPEG com 70% de qualidade para reduzir drasticamente o tamanho sem perder muita definição
      resolve(canvas.toDataURL('image/jpeg', 0.7));
    };
  });
};

