          <div className="p-8 border-2 border-dashed border-orange-200 rounded-3xl space-y-4">
            <div className="flex items-center gap-2"><span className="text-2xl text-red-500">▶️</span><span className="text-gray-600 font-medium">Link Externo</span></div>
            <input type="text" placeholder="Link do vídeo ou post..." className="w-full p-3 border rounded-xl text-sm" value={videoUrl} onChange={e => setVideoUrl(e.target.value)} />
            <div className="flex gap-2">
              <button onClick={handleVideoTranscribe} className="flex-1 py-3 bg-orange-300 text-white rounded-xl font-bold text-sm">IA Extrair</button>
              <button onClick={() => { setFormData({...formData, externalLink: videoUrl}); setStep('form'); }} className="flex-1 py-3 bg-gray-50 text-gray-400 rounded-xl font-bold text-sm">Só Link</button>
            </div>
          </div>
          <button onClick={() => setStep('form')} className="w-full p-8 border-2 border-dashed border-orange-200 rounded-3xl hover:bg-orange-50 text-center flex flex-col items-center"><div className="text-4xl mb-2 text-pati-orange">🖋️</div><span className="text-gray-600 font-medium">Digitar Receita</span></button>
          <div className="p-8 border-2 border-dashed border-orange-200 rounded-3xl space-y-4 text-center">
            <div className="text-4xl mb-2">🍜</div><span className="text-gray-600 font-medium">O que cozinhar?</span>
