                  <img src={p.photoUrl || DEFAULT_PROFILE_IMAGE} className="w-28 h-28 rounded-full border-2 border-gray-100 group-hover:border-pati-orange shadow-md object-cover mb-3 transition-all transform group-hover:scale-105" />
                  <span className="font-semibold text-gray-700">{p.name}</span>
                </button>
                <div className="absolute top-0 right-0 flex flex-col gap-2">
                  <button onClick={(e) => { e.stopPropagation(); handleEditProfileClick(p); }} className="bg-white shadow-md border border-gray-100 p-2 rounded-full text-xs hover:text-pati-orange transition-colors">✏️</button>
                  <button onClick={(e) => { e.stopPropagation(); handleDeleteProfile(p.id); }} className="bg-white shadow-md border border-gray-100 p-2 rounded-full text-xs hover:text-red-500 transition-colors">🗑️</button>
                </div>
              </div>
            ))}
            <button onClick={() => { setEditingProfile(null); setNewProfileName(''); setNewProfilePhoto(''); setNewProfileBirth(''); setView(AppView.PROFILE_CREATE); }} className="flex flex-col items-center group">
