            <p className="text-yellow-800 text-sm italic">{recipe.tips}</p>
          </div>
        )}

        {timerLabels.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {timerLabels.map((l: string, i: number) => (
              <button key={i} onClick={() => {
                const num = parseInt(l);
                const isHours = l.toLowerCase().includes('h');
                onStartTimer(isHours ? num * 3600 : num * 60, l);
              }} className="bg-blue-50 text-blue-600 px-4 py-2 rounded-full text-xs font-bold border border-blue-100 shadow-sm transition-all hover:bg-blue-100">⏱️ Iniciar {l}</button>
            ))}
