                ))}
              </div>
              <a href={WHATSAPP_GROUP_URL} target="_blank" rel="noopener noreferrer" className="w-full text-left px-4 py-4 rounded-xl font-bold text-green-600 bg-green-50 flex items-center justify-center gap-2 mt-4 shadow-sm hover:bg-green-100 transition-colors">
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 448 512"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-5.5-2.8-23.4-8.6-44.6-27.6-16.5-14.7-27.6-32.8-30.8-38.4-3.2-5.6-.3-8.6 2.5-11.4 2.5-2.5 5.5-6.5 8.3-9.8 2.8-3.2 3.7-5.5 5.5-9.2 1.9-3.7.9-7-.5-9.8-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 13.2 5.8 23.5 9.2 31.5 11.8 13.3 4.2 25.4 3.6 35 2.2 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg>
                Grupo da Família
              </a>
            </aside>
          )}

          <main className="flex-1 min-w-0">
            {view === AppView.HOME && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                {filteredRecipes.length === 0 ? (
                    <div className="col-span-full text-center py-24 text-gray-400">Poxa, nenhuma receita aqui! Cozinhe algo novo!</div>
                ) : (
                  filteredRecipes.map(recipe => {
                    const author = profiles.find(p => p.id === recipe.authorId);
                    return (
                      <div key={recipe.id} className="bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl border border-gray-100 cursor-pointer transition-all flex flex-col group" onClick={() => { setEditingRecipe(recipe); setView(AppView.RECIPE_DETAIL); }}>
                        <div className="relative h-44 overflow-hidden">
                          <img src={recipe.imageUrl || DEFAULT_RECIPE_IMAGE} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                          <div className="absolute top-2 right-2 flex flex-col gap-2">
                            <button onClick={(e) => { e.stopPropagation(); toggleFavorite(recipe.id); }} className="w-10 h-10 rounded-full bg-white/90 shadow-md flex items-center justify-center text-xl transition-transform hover:scale-110">{recipe.isFavorite ? '❤️' : '🤍'}</button>
                            {recipe.externalLink && (
                              <div className="w-10 h-10 rounded-full bg-blue-500 shadow-md flex items-center justify-center text-white text-xs transition-transform hover:scale-110" title="Possui link externo">🔗</div>
                            )}
                          </div>
                        </div>
                        <div className="p-4 flex-1">
                          <h3 className="font-bold text-gray-800 text-lg mb-3 leading-tight group-hover:text-pati-orange transition-colors">{recipe.title}</h3>
                          <div className="flex items-center gap-2 mt-auto border-t border-gray-50 pt-3">
                            <img src={author?.photoUrl || DEFAULT_PROFILE_IMAGE} className="w-6 h-6 rounded-full object-cover border border-gray-200" />
                            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">DE: {recipe.authorName}</p>
                          </div>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}
            {view === AppView.RECIPE_DETAIL && editingRecipe && (
              <RecipeDetailView recipe={editingRecipe} onBack={() => setView(AppView.HOME)} onEdit={() => setView(AppView.RECIPE_EDIT)} onDelete={() => deleteRecipe(editingRecipe.id)} onToggleFavorite={() => toggleFavorite(editingRecipe.id)} onAddComment={(t: string) => addComment(editingRecipe.id, t)} onStartTimer={(s: number, l: string) => setActiveTimer({ seconds: s, label: l })} onWhatsAppShare={() => handleWhatsAppShare(editingRecipe.title)} />
            )}
            {(view === AppView.RECIPE_EDIT || view === AppView.AI_TOOLS) && (
              <RecipeForm recipe={editingRecipe || undefined} activeProfile={activeProfile} onSave={saveRecipe} onCancel={() => setView(AppView.HOME)} isAiLoading={isAiLoading} setIsAiLoading={setIsAiLoading} />
            )}
          </main>
        </div>
        {view === AppView.HOME && (
          <button onClick={() => { setEditingRecipe(null); setView(AppView.RECIPE_EDIT); }} className="fixed bottom-8 right-8 w-16 h-16 bg-pati-orange text-white text-3xl rounded-full shadow-2xl flex items-center justify-center z-50 hover:scale-110 active:scale-95 transition-all">+</button>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex flex-col bg-white">
      <div className="flex-grow">{renderContent()}</div>
      <Footer />
    </div>
  );
};

const RecipeDetailView = ({ recipe, onBack, onEdit, onDelete, onToggleFavorite, onAddComment, onStartTimer, onWhatsAppShare }: any) => {
  const [portionFactor, setPortionFactor] = useState(1);
  const [adjustedIngredients, setAdjustedIngredients] = useState(recipe.ingredients);
  const [isAdjusting, setIsAdjusting] = useState(false);
  const [commentText, setCommentText] = useState('');
  const handleAdjust = async (val: number) => {
    setPortionFactor(val);
    setIsAdjusting(true);
    try {
      const adjusted = await gemini.adjustPortions(recipe.ingredients, val);
      setAdjustedIngredients(adjusted);
    } catch (err) { alert("Erro ao ajustar porções."); } finally { setIsAdjusting(false); }
  };
  const timerLabels = (recipe.instructions.match(/\d+\s*(minutos|min|horas|h)/gi) || []);
  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl max-w-3xl mx-auto border border-gray-100 space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="text-pati-orange font-bold flex items-center gap-2">← Voltar</button>
        <div className="flex gap-4 items-center">
          <button onClick={onWhatsAppShare} className="text-green-500"><svg className="w-6 h-6" fill="currentColor" viewBox="0 0 448 512"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-5.5-2.8-23.4-8.6-44.6-27.6-16.5-14.7-27.6-32.8-30.8-38.4-3.2-5.6-.3-8.6 2.5-11.4 2.5-2.5 5.5-6.5 8.3-9.8 2.8-3.2 3.7-5.5 5.5-9.2 1.9-3.7.9-7-.5-9.8-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 13.2 5.8 23.5 9.2 31.5 11.8 13.3 4.2 25.4 3.6 35 2.2 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg></button>
          <button onClick={onToggleFavorite} className="text-2xl">{recipe.isFavorite ? '❤️' : '🤍'}</button>
          <button onClick={onEdit} className="text-xl">✏️</button>
          <button onClick={onDelete} className="text-xl text-red-400">🗑️</button>
        </div>
      </div>
      <div className="relative group overflow-hidden rounded-3xl">
        <img src={recipe.imageUrl || DEFAULT_RECIPE_IMAGE} className="w-full h-80 object-cover shadow-md transition-transform duration-700 group-hover:scale-105" />
        <button onClick={onEdit} className="absolute bottom-4 right-4 bg-white/90 backdrop-blur-sm text-pati-orange px-6 py-3 rounded-full font-bold text-xs shadow-xl opacity-0 group-hover:opacity-100 transition-all active:scale-95">Alterar Imagem da Receita</button>
      </div>
      <div>
        <h2 className="text-4xl font-cursive text-gray-800 mb-2">{recipe.title}</h2>
        <div className="flex flex-wrap gap-2 items-center">
          <span className="bg-orange-100 text-pati-orange text-[10px] font-bold uppercase px-3 py-1 rounded-full">{CATEGORIES.find(c => c.id === recipe.category)?.label}</span>
          {recipe.externalLink && (
            <a href={recipe.externalLink} target="_blank" className="bg-blue-100 text-blue-600 text-[10px] font-bold uppercase px-3 py-1 rounded-full flex items-center gap-1 hover:bg-blue-200 transition-colors">
              🔗 Ver Link Original
            </a>
          )}
        </div>
      </div>

      <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100">
        <div className="flex justify-between items-center mb-4">
          <h4 className="font-bold text-pati-orange text-sm uppercase tracking-[0.2em]">🥘 Ajustar Porções</h4>
          <div className="flex items-center gap-3">
            <button onClick={() => handleAdjust(Math.max(0.5, portionFactor - 0.5))} className="w-8 h-8 rounded-full bg-white text-pati-orange shadow flex items-center justify-center font-bold transition-transform active:scale-90">-</button>
            <span className="font-bold text-sm">{portionFactor}x</span>
            <button onClick={() => handleAdjust(portionFactor + 0.5)} className="w-8 h-8 rounded-full bg-white text-pati-orange shadow flex items-center justify-center font-bold transition-transform active:scale-90">+</button>
          </div>
        </div>
        <div className={`text-gray-700 whitespace-pre-wrap leading-relaxed text-sm ${isAdjusting ? 'opacity-30' : ''}`}>{adjustedIngredients}</div>
      </div>

      <div className="space-y-6">
        <div className="space-y-4">
          <h4 className="font-bold text-gray-400 text-sm uppercase tracking-widest">🔥 Modo de Preparo</h4>
          <p className="text-gray-700 whitespace-pre-wrap leading-loose text-sm">{recipe.instructions}</p>
        </div>

        {recipe.tips && (
          <div className="p-6 bg-yellow-50 rounded-2xl border border-yellow-100 space-y-2 fade-in">
            <h4 className="font-bold text-yellow-700 text-xs uppercase tracking-[0.2em] flex items-center gap-2">💡 Dica da {recipe.authorName}</h4>
            <p className="text-yellow-800 text-sm italic leading-relaxed">{recipe.tips}</p>
          </div>
        )}

        {timerLabels.length > 0 && (
          <div className="flex flex-wrap gap-2 pt-2">
            {timerLabels.map((l: string, i: number) => (
              <button key={i} onClick={() => {
                const num = parseInt(l);
                const isHours = l.toLowerCase().includes('h');
                onStartTimer(isHours ? num * 3600 : num * 60, l);
              }} className="bg-blue-50 text-blue-600 px-4 py-2 rounded-full text-xs font-bold border border-blue-100 shadow-sm transition-all hover:bg-blue-100 hover:scale-105 active:scale-95">⏱️ Iniciar Timer {l}</button>
            ))}
          </div>
        )}
      </div>

      <div className="pt-8 border-t border-gray-100">
        <h4 className="font-bold text-gray-400 text-sm uppercase tracking-widest mb-4">💬 Comentários</h4>
        <div className="space-y-4 mb-6">{(recipe.comments || []).map((c: any) => (
          <div key={c.id} className="bg-gray-50 p-4 rounded-2xl border border-gray-100 fade-in">
            <p className="text-xs font-bold text-pati-orange mb-1">{c.authorName}</p>
            <p className="text-sm text-gray-700">{c.text}</p>
          </div>
        ))}</div>
        <div className="flex gap-2">
          <input type="text" placeholder="Escreva algo..." className="flex-1 p-3 border-2 border-gray-50 rounded-xl text-sm outline-none focus:border-pati-orange transition-all" value={commentText} onChange={e => setCommentText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (onAddComment(commentText), setCommentText(''))} />
          <button onClick={() => { onAddComment(commentText); setCommentText(''); }} className="bg-pati-orange text-white px-6 rounded-xl font-bold text-xs uppercase shadow-sm transition-all active:scale-95">Enviar</button>
        </div>
      </div>
    </div>
  );
};

const RecipeForm = ({ recipe, activeProfile, onSave, onCancel, isAiLoading, setIsAiLoading }: any) => {
  const [step, setStep] = useState(recipe ? 'form' : 'options');
  const [formData, setFormData] = useState<Partial<Recipe>>(recipe || { title: '', category: 'outros' as any, ingredients: '', instructions: '', tips: '', authorName: activeProfile?.name || '' });
  const [videoUrl, setVideoUrl] = useState('');
  const [suggestionInput, setSuggestionInput] = useState('');

  const handleSimpleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const compressed = await compressImage(reader.result as string, 800);
        setFormData(prev => ({ ...prev, imageUrl: compressed }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsAiLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const compressed = await compressImage(reader.result as string, 800);
      try {
        const result = await gemini.transcribeImage(compressed.split(',')[1]);
        setFormData(prev => ({ ...prev, ...result, imageUrl: compressed }));
        setStep('form');
      } catch (err) { 
        alert('Erro na transcrição por IA. Tente manualmente.'); 
        setFormData(prev => ({ ...prev, imageUrl: compressed }));
        setStep('form');
      } finally { setIsAiLoading(false); }
    };
    reader.readAsDataURL(file);
  };

  const handleVideoTranscribe = async () => {
    if (!videoUrl) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.transcribeVideoLink(videoUrl);
      setFormData(prev => ({ ...prev, ...result, externalLink: videoUrl }));
      setStep('form');
    } catch (err) { 
      alert('IA falhou no vídeo, link salvo.'); 
      setFormData(prev => ({ ...prev, externalLink: videoUrl }));
      setStep('form');
    } finally { setIsAiLoading(false); }
  };

  const handleSuggestion = async () => {
    if (!suggestionInput) return;
    setIsAiLoading(true);
    try {
      const result = await gemini.getRecipeSuggestions(suggestionInput);
      setFormData(prev => ({ ...prev, ...result }));
      setStep('form');
    } catch (err) { alert('IA falhou.'); } finally { setIsAiLoading(false); }
  };

  if (step === 'options') {
    return (
      <div className="bg-white rounded-3xl p-8 shadow-lg max-w-lg mx-auto space-y-6 border border-gray-100 fade-in">
        <h2 className="text-2xl font-bold text-gray-800">Nova Receita</h2>
        <div className="space-y-4">
          <label className="block p-8 border-2 border-dashed border-orange-200 rounded-3xl cursor-pointer hover:bg-orange-50 text-center transition-all">
            <div className="text-4xl mb-2">📷</div>
            <span className="text-gray-600 font-medium">Foto/Scanner</span>
            <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
          </label>
          <div className="p-8 border-2 border-dashed border-orange-200 rounded-3xl space-y-4">
            <div className="flex items-center gap-2"><span className="text-2xl text-red-500">▶️</span><span className="text-gray-600 font-medium">Link Externo</span></div>
            <input type="text" placeholder="Link do vídeo ou post..." className="w-full p-3 border rounded-xl text-sm outline-none focus:border-pati-orange" value={videoUrl} onChange={e => setVideoUrl(e.target.value)} />
            <div className="flex gap-2">
              <button onClick={handleVideoTranscribe} className="flex-1 py-3 bg-orange-300 text-white rounded-xl font-bold text-sm transition-all active:scale-95">IA Extrair</button>
              <button onClick={() => { setFormData({...formData, externalLink: videoUrl}); setStep('form'); }} className="flex-1 py-3 bg-gray-50 text-gray-400 rounded-xl font-bold text-sm transition-all active:scale-95">Só Link</button>
            </div>
          </div>
          <button onClick={() => setStep('form')} className="w-full p-8 border-2 border-dashed border-orange-200 rounded-3xl hover:bg-orange-50 text-center flex flex-col items-center transition-all active:scale-95"><div className="text-4xl mb-2 text-pati-orange">🖋️</div><span className="text-gray-600 font-medium">Digitar Receita</span></button>
          <div className="p-8 border-2 border-dashed border-orange-200 rounded-3xl space-y-4 text-center">
            <div className="text-4xl mb-2">🍜</div><span className="text-gray-600 font-medium">O que cozinhar?</span>
            <input type="text" placeholder="O que tem na geladeira?" className="w-full p-2 border rounded-lg text-xs outline-none focus:border-pati-orange" value={suggestionInput} onChange={e => setSuggestionInput(e.target.value)} />
            <button onClick={handleSuggestion} className="w-full py-2 bg-pati-orange text-white text-xs rounded-lg font-bold transition-all active:scale-95">Sugestão IA</button>
          </div>
        </div>
        <button onClick={onCancel} className="w-full py-4 text-gray-400 font-bold hover:text-gray-600">Cancelar</button>
        {isAiLoading && <div className="fixed inset-0 bg-white/80 flex items-center justify-center z-[100] font-cursive text-2xl text-pati-orange animate-pulse">A IA está preparando...</div>}
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-8 shadow-lg space-y-6 border border-gray-100 max-w-3xl mx-auto fade-in">
      <h2 className="text-2xl font-bold text-gray-800">{recipe ? 'Editar' : 'Nova'} Receita</h2>

      <div className="space-y-2">
        <label className="text-xs font-bold text-gray-400 uppercase tracking-widest">Imagem da Receita</label>
        <div className="relative group h-48 rounded-2xl overflow-hidden bg-gray-50 border border-gray-100">
          <img src={formData.imageUrl || DEFAULT_RECIPE_IMAGE} className="w-full h-full object-cover" />
          <label className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer text-white font-bold text-xs uppercase tracking-widest">
            Alterar Foto
            <input type="file" accept="image/*" className="hidden" onChange={handleSimpleImageUpload} />
          </label>
        </div>
      </div>

      <div className="space-y-4">
        <input type="text" placeholder="Título da Receita" className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange" value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} />
        <select className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange bg-white" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value as any })}>
