        </select>
        <input type="text" placeholder="De quem é essa receita? (ex: Nome do autor)" className="w-full p-4 border rounded-xl outline-none focus:border-pati-orange" value={formData.authorName} onChange={e => setFormData({ ...formData, authorName: e.target.value })} />
        <textarea placeholder="Dicas da receita (ex: 'O segredo é deixar a massa descansar 20 min')" className="w-full p-4 border rounded-xl h-24 outline-none focus:border-pati-orange resize-none" value={formData.tips} onChange={e => setFormData({ ...formData, tips: e.target.value })} />
        <textarea placeholder="Ingredientes (ex: 2 ovos, 1 xícara de farinha...)" className="w-full p-4 border rounded-xl h-40 outline-none focus:border-pati-orange resize-none" value={formData.ingredients} onChange={e => setFormData({ ...formData, ingredients: e.target.value })} />
        <textarea placeholder="Modo de Preparo (ex: 1. Bata tudo no liquidificador...)" className="w-full p-4 border rounded-xl h-60 outline-none focus:border-pati-orange resize-none" value={formData.instructions} onChange={e => setFormData({ ...formData, instructions: e.target.value })} />
        <div className="flex gap-4 pt-4">
          <button onClick={recipe ? onCancel : () => setStep('options')} className="flex-1 py-4 border-2 border-gray-100 rounded-2xl font-bold text-gray-400 transition-all hover:bg-gray-50">Voltar</button>
          <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-2xl font-bold shadow-lg transition-all hover:bg-orange-600">Salvar no Meu Caderno</button>
        </div>
      </div>
    </div>
  );
};

