      const newFavoritedBy = favoritedBy.includes(activeProfile.id)
        ? favoritedBy.filter(id => id !== activeProfile.id)
        : [...favoritedBy, activeProfile.id];
      await updateDoc(doc(db, "recipes", recipeId), { favoritedBy: newFavoritedBy });
    }
  };

