                  className="inline-flex items-center gap-2 text-pati-orange text-xs font-bold hover:underline bg-orange-50 px-4 py-2 rounded-full transition-colors hover:bg-orange-100"
                >
                  <span>📍</span> Não tem uma chave? Clique aqui para obter grátis
                </a>
              </div>
            </div>
            {loginError && (
              <div className="p-4 bg-red-50 rounded-xl border border-red-100 flex items-center gap-3 text-red-500">
