              <button onClick={() => setSearch(tempSearch)} className="bg-pati-orange text-white px-4 rounded-xl font-bold text-xs uppercase shadow-sm">Buscar</button>
            </div>
          )}
        </header>

        <div className="p-4 max-w-6xl mx-auto flex flex-col md:flex-row gap-6">
