        <textarea placeholder="Modo de Preparo (ex: 1. Bata tudo no liquidificador...)" className="w-full p-4 border rounded-xl h-60 outline-none focus:border-pati-orange resize-none" value={formData.instructions} onChange={e => setFormData({ ...formData, instructions: e.target.value })} />

        <div className="flex flex-col gap-4 pt-4">
          <div className="flex gap-4">
            <button onClick={recipe ? onCancel : () => setStep('options')} className="flex-1 py-4 border-2 border-gray-100 rounded-2xl font-bold text-gray-400 transition-all hover:bg-gray-50">Voltar</button>
            <button onClick={() => onSave(formData)} className="flex-[2] py-4 bg-pati-orange text-white rounded-2xl font-bold shadow-lg transition-all hover:bg-orange-600">Salvar no Meu Caderno</button>
          </div>

          {suggestionInput && !recipe && (
             <button onClick={handleSuggestion} className="w-full py-4 border-2 border-pati-orange text-pati-orange rounded-2xl font-bold transition-all hover:bg-orange-50 flex items-center justify-center gap-2">
               🔄 Não gostou? Gerar Outra Opção
             </button>
          )}
        </div>
      </div>
    </div>
  );
};

